(window.__BOOKS=window.__BOOKS||{})["e_alcestis"]={"b":[["h2","Действующие лица"],["person","<span class=\"pn\">Аполлон</span>"],["person","<span class=\"pn\">Демон Смерти</span>"],["person","<span class=\"pn\">Хор</span>"],["person","<span class=\"pn\">Служанка</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"alkesta\">Алькеста</span></span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"admet\">Адмет</span></span>"],["person","<span class=\"pn\">Евмел</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"gerakl\">Геракл</span></span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"feret\">Ферет</span></span>"],["person","<span class=\"pn\">Слуга</span>"],["place","Действие происходит в Фессалии, близ города Фер."],["act","Пролог","a1",""],["sd","Сцена представляет фасад дворца в дорийском стиле. Раннее утро. Из дворца выходит Аполлон. На нем поверх одежды колчан, в руках лук."],["scene","Явление первое","s1",1,1],["sp","Аполлон"],["v","Вот дом царя <span class=\"ch\" data-ch=\"admet\">Адмета</span>, где, бессмертный,",0,1,0,0],["v","Я трапезу поденщиков делил",0,1,0,0],["v","По Зевсовой вине. Когда перуном",0,1,0,0],["v","Асклепия сразил он, злою долей<a class=\"nr\" href=\"#n-k1\" data-n=\"k1\" aria-label=\"Примечание 1\">1</a>",0,2,0,0],["v","Сыновнею разгневанный, в ответ",0,3,0,0],["v","Я перебил киклопов, ковачей",0,4,0,0],["v","Его перуна грозного; карая,",0,5,0,0],["v","Быть батраком у смертного отец",0,6,0,0],["v","Мне положил: и вот, на эту землю",0,7,0,0],["v","Сойдя, поднесь стада на ней я пас",0,8,0,0],["v","И дом стерег. Слуга благочестивый,",0,9,0,0],["v","Благочестивому царю я жизнь,",0,10,1,1],["v","Осилив дев судьбы, сберег коварством:",0,10,0,0],["v","Мне обещали Мойры, что <span class=\"ch\" data-ch=\"admet\">Адмет</span>,<a class=\"nr\" href=\"#n-k2\" data-n=\"k2\" aria-label=\"Примечание 2\">2</a>",0,11,0,0],["v","<span class=\"ch\" data-ch=\"feret\">Ферета</span> сын, приспевшего Аида",0,12,0,0],["v","Избавится, коль жертвою иной",0,13,0,0],["v","Поддонных сил он утолит желанья;",0,14,0,0],["v","Царь испытал всех присных: ни отца,",0,15,0,0],["v","Ни матери не миновал он старой,",0,16,0,0],["v","Но друга здесь в одной жене обрел,",0,17,0,0],["v","Кто б возлюбил Аидов мрак за друга.",0,18,0,0],["v","Царицу там теперь в разлуке с жизнью",0,19,1,0],["v","И ноги уж не носят. Подошла",0,20,0,1],["v","Преставиться ей тяжкая година…",0,21,0,0],["v","Пора и мне излюбленную сень",0,22,0,0],["v","Покинуть — вежд да не коснется скверна.<a class=\"nr\" href=\"#n-k3\" data-n=\"k3\" aria-label=\"Примечание 3\">3</a>",0,23,0,0],["sd","На сцену появляется Демон Смерти, огромный, в развевающейся черной одежде, с ярко-красными губами и большим черным мечом."],["v","Уж вот он, смерти демон, этот жрец",0,24,0,0],["v","Над трупами. В чертог Аидов он",0,25,0,0],["v","Ее повлечь готов. Как сторож зоркий,",0,26,0,0],["v","Пройти не даст он роковому дню.",0,27,0,0],["scene","Явление второе","s2",1,2],["sp","Аполлон и Демон Смерти"],["sd","Демон Смерти (не приближаясь к Аполлону)"],["v","А!.. Ты… опять… Аполлон?",0,28,0,0],["v","Что забыл? Ты зачем у чертога",0,30,0,1],["v","Бродишь, Феб, и опять",0,30,0,0],["v","У поддонных дары",0,31,0,0],["v","Отнимаешь, обидчик, зачем?",0,32,0,0],["v","Или мало тебе, что <span class=\"ch\" data-ch=\"admet\">Адмету</span>",0,33,0,0],["v","Умереть помешал, что искусством",0,34,0,0],["v","Дев судьбы осилил коварным?",0,35,0,0],["v","Что рукою за лук берешься?",0,35,0,0],["v","Разве Пелия дочь не сама",0,36,0,0],["v","Умереть желала за мужа?",0,37,0,0],["sp","Аполлон"],["v","Дерзай: со мной лишь истина и слава.<a class=\"nr\" href=\"#n-k4\" data-n=\"k4\" aria-label=\"Примечание 4\">4</a>",0,38,0,0],["sp","Демон"],["v","Лишь истина? А этот лук зачем?",0,39,0,0],["sp","Аполлон"],["v","Его носить велит привычка, демон.",0,40,0,1],["sp","Демон"],["v","Чтобы домам, как этот, помогать,",0,40,0,0],["v","Хотя бы против правды, бог, не так ли?",0,41,0,0],["sp","Аполлон"],["v","Мне тягостно несчастие друзей.",0,42,0,0],["sp","Демон"],["v","И ты лишишь меня второго трупа?",0,43,0,0],["sp","Аполлон"],["v","Я силою и первого не брал.",0,43,0,0],["sp","Демон"],["v","Он на земле, однако ж, не в могиле.",0,44,0,0],["sp","Аполлон"],["v","Сменен женой… И ты пришел за ней.",0,45,0,0],["sp","Демон"],["v","Да, чтоб увлечь ее в земные недра.",0,46,0,0],["sp","Аполлон"],["v","Что ж? Уноси ее… Разубедить",0,46,0,0],["v","Едва ли я тебя сумею, демон.",0,47,0,0],["sp","Демон"],["v","Не для того ль, державный Аполлон,",0,48,0,0],["v","И призван я, чтоб убивать мне данных?",0,49,0,0],["sp","Аполлон"],["v","На медлящих оковы налагай…",0,50,0,1],["sp","Демон"],["v","О, я для них всегда к твоим услугам.",0,51,0,0],["sp","Аполлон"],["dir","помолчав"],["v","До старости ты ей не дашь дожить?",0,52,0,0],["sp","Демон"],["v","И смерти мил бывает дар почетный.",0,53,0,0],["sp","Аполлон"],["v","Но жизнь одну, не больше ж ты возьмешь.",0,54,0,0],["sp","Демон"],["v","Нам жизни дар отраднее цветущей.",0,55,0,0],["sp","Аполлон"],["v","А у старухи роскошь похорон?",0,56,0,0],["sp","Демон"],["v","Иль твой закон рассчитан на богатых?",0,57,0,0],["sp","Аполлон"],["dir","иронически"],["v","Вот тонкий ум… Кто мог бы ожидать?",0,58,0,0],["sp","Демон"],["dir","продолжая"],["v","До старости от Смерти откупаться…",0,59,0,0],["sp","Аполлон"],["dir","помолчав"],["v","Итак, <span class=\"ch\" data-ch=\"alkesta\">Алькесты</span> мне ты не отдашь?",0,60,0,1],["sp","Демон"],["v","Да, не отдам. Ты мой характер знаешь…",0,60,0,0],["sp","Аполлон"],["v","Для смертных яд, остуда для богов.",0,61,0,0],["sp","Демон"],["v","Недолжного с меня не взять словами.",0,62,0,0],["sp","Аполлон"],["v","Как ни жесток ты, Демон, ты уступишь…",0,63,0,0],["v","Такой сюда от Еврисфея муж",0,64,0,0],["v","Дорогою зайдет, за колесницей<a class=\"nr\" href=\"#n-k5\" data-n=\"k5\" aria-label=\"Примечание 5\">5</a>",0,65,0,0],["v","К фракийцам направляясь, чтоб коней",0,66,0,0],["v","Царю добыть, из края зим суровых.",0,67,0,0],["v","И, принят здесь, в Адметовом дому,",0,68,0,0],["v","Он у тебя царицу силой вырвет.",0,69,0,0],["v","Бессмертному ты отказал. А все ж",0,70,0,1],["v","По-моему ты сделаешь. И прибыль",0,70,0,0],["v","Тебе одна — мое негодованье…",0,71,0,0],["sd","(Уходит.)"],["scene","Явление третье","s3",1,3],["sp","Демон"],["dir","один"],["v","Так много слов и даром… И жена",0,72,0,0],["v","В Аидов дом сойдет… Я к ней приближусь",0,73,0,0],["v","И до нее мечом коснусь… а чьих",0,74,0,0],["v","Мой черный меч волос коснется, ада",0,75,0,0],["v","Уж посвящен властительным богам.",0,76,0,0],["sd","(Входит в дом.)"],["sd","Во дворце воцаряется полная и зловещая тишина. На орхестру спускается хор ферейских граждан. Сначала немая сцена. Ферейцы сходятся в группы, расходятся и, глядя на дворец, знаками высказывают друг другу свои недоумения. В их движении чувствуется сдержанная тревога."],["scene","Явление четвертое","s4",1,4],["scene","Вступительная песнь хора","s5",1,5],["v","На орхестру вступает хор.",0,77,0,0],["sp","Хор"],["v","Какой тишиною чертог объят!..",0,78,0,0],["v","Как немы палаты <span class=\"ch\" data-ch=\"admet\">Адмета</span>.",0,79,0,0],["v","Нигде… ни души… Скажите ж:",0,80,0,1],["v","Мне оплакать ли Пелия дочерь,",0,81,0,0],["v","Иль царица <span class=\"ch\" data-ch=\"alkesta\">Алькеста</span> жива еще",0,82,0,0],["v","И лучи еще видят солнца",0,83,0,0],["v","Ту, которой из жен для мужа",0,84,0,0],["v","Благородней в мире не знаю?..",0,85,0,0],["sp","Первое полухорие"],["sd","Строфа I В чертоге не внемлешь ли стонам? Иль скорби ударам глухим?.."],["v","Пауза: прислушиваются, потом тихо:",0,86,0,0],["v","Там стон не сказал ли: «Свершилось?»",0,87,0,0],["sp","Второе полухорие"],["v","Слуги у ворот",0,90,0,1],["v","На страже не вижу… Безвестьем",0,90,0,0],["v","Томлюсь я… Но бедствия волны",0,91,0,0],["v","Не ты ль, о Пеан, рассечешь?<a class=\"nr\" href=\"#n-k6\" data-n=\"k6\" aria-label=\"Примечание 6\">6</a>",0,92,0,0],["sp","Первое полухорие"],["v","Над мертвой бы там не молчали…",0,92,0,0],["sp","Второе полухорие"],["v","Она умерла…",0,93,0,0],["sp","Первое полухорие"],["v","Ее унести не могли же.",0,94,0,0],["sp","Второе полухорие"],["v","Как знать?.. Сомневаюсь и страшно…",0,95,0,0],["v","Но что ж ободряет тебя?",0,95,0,0],["sp","Первое полухорие"],["v","Ужели б <span class=\"ch\" data-ch=\"admet\">Адмет</span>",0,96,0,0],["v","Безлюдным бы выносом тело",0,97,0,0],["v","Любимой жены опозорил?",0,97,0,0],["sp","Второе полухорие"],["str","Антистрофа I"],["v","В воротах чертога не вижу",0,98,0,0],["v","Обряда воды ключевой.<a class=\"nr\" href=\"#n-k7\" data-n=\"k7\" aria-label=\"Примечание 7\">7</a>",0,99,0,0],["v","Покойника не было в доме.",0,100,0,1],["sp","Первое полухорие"],["v","Я сбритых волос,",0,100,0,0],["v","Что в скорби с голов упадают,<a class=\"nr\" href=\"#n-k8\" data-n=\"k8\" aria-label=\"Примечание 8\">8</a>",0,101,0,0],["v","Не вижу… Там юные руки",0,102,0,0],["v","О перси в печали не бьют…",0,103,0,0],["sp","Второе полухорие"],["v","Но день роковой не свершился.",0,104,0,0],["sp","Первое полухорие"],["v","Какие слова!",0,105,0,0],["sp","Второе полухорие"],["v","Землей ей сегодня покрыться.",0,106,0,0],["sp","Первое полухорие"],["v","По сердцу и мыслям провел ты",0,107,0,0],["v","Мне скорби тяжелым смычком.",0,108,0,0],["sp","Второе полухорие"],["v","Коль смертью, кто благ",0,109,0,0],["v","И людям всегда был полезен,",0,110,0,1],["v","Терзается, как же не плакать?",0,111,0,0],["sp","Первое полухорие"],["str","Строфа II"],["v","Куда бы ни слать корабли",0,112,0,0],["v","С дарами по влажному лону,",0,113,0,0],["v","К святыням ликийской земли,<a class=\"nr\" href=\"#n-k10\" data-n=\"k10\" aria-label=\"Примечание 10\">10</a>",0,114,0,0],["v","К безводному ль Аммона трону,",0,115,0,0],["v","Напрасно бы длился их путь…",0,116,0,0],["v","Уж к солнцу души не вернуть",0,117,0,0],["v","Со скал неприступно-отвесных…",0,118,0,0],["v","Какого ж мне бога молить",0,120,0,1],["v","И крови овечьей полить",0,120,0,0],["v","Кому на алтарь из небесных?",0,121,0,0],["sp","Второе полухорие"],["str","Антистрофа II"],["v","О, если бы солнца лучи",0,122,0,0],["v","Рожденному Фебом светили,",0,123,0,0],["v","<span class=\"ch\" data-ch=\"alkesta\">Алькесту</span> из адской ночи",0,124,0,0],["v","Ворота б теперь отпустили.",0,125,0,0],["v","Имел воскресителя дар",0,125,0,0],["v","Асклепий… Но тяжкий удар",0,126,0,0],["v","Перуна небес огневого",0,127,0,0],["v","Уносит и мощь и красу…",0,128,0,0],["v","К кому же теперь вознесу",0,129,0,0],["v","С надеждой молящее слово?",0,130,0,1],["str","Эпод"],["v","Все было сделано царем…",0,130,0,0],["v","Тут были жертвы без числа,",0,131,0,0],["v","И кровь пред каждым алтарем",0,132,0,0],["v","Без меры чистая текла,",0,133,0,0],["v","Но исцеленья нет от зла.",0,134,0,0],["act","Действие первое","a2","I"],["scene","Явление пятое","s6",2,6],["sd","Те же, и из дворца выходит служанка. Она не в трауре, но в слезах. Пока она спускается в орхестру, —"],["sp","Корифей"],["v","Постойте. Вот выходит из чертога<a class=\"nr\" href=\"#n-k9\" data-n=\"k9\" aria-label=\"Примечание 9\">9</a>",0,135,0,0],["v","Прислужница в слезах… Какую весть",0,136,0,0],["v","Она несет? Печалию облечься",0,137,0,0],["v","Простительно пред царскою бедой.",0,138,0,0],["sd","Хор окружает служанку со знаками живейшего внимания."],["v","Жива ль она, царица, или смертью",0,139,0,0],["v","Осилена?.. Мы бы хотели знать…",0,140,0,1],["sp","Служанка"],["v","Считай ее живущей и умершей…",0,141,0,0],["sp","Корифей"],["v","Иль человек умерший видит свет?",0,142,0,0],["sp","Служанка"],["v","Она томится расставаньем с жизнью.",0,143,0,0],["sp","Корифей"],["v","Адмет, Адмет! Кого теряешь ты?",0,144,0,0],["sp","Служанка"],["v","Лишь мертвую ее <span class=\"ch\" data-ch=\"admet\">Адмет</span> оценит.",0,145,0,0],["sp","Корифей"],["v","Спасти ее надежды больше нет?",0,146,0,0],["sp","Служанка"],["v","Сужденный день творит над ней насилье.",0,147,0,0],["sp","Корифей"],["v","Как? Иль на смерть ее сбирают там…",0,148,0,0],["sp","Служанка"],["v","Уж и наряд готов, в чем муж схоронит.",0,149,0,0],["sp","Корифей"],["v","О, славная решимость умереть,",0,150,0,1],["v","О, лучшая из жен под солнцем дальним!",0,150,0,0],["sp","Служанка"],["v","Да, лучшая. Кто станет возражать?",0,151,0,0],["v","Иль что же сделать надо, чтобы лучшей",0,152,0,0],["v","Из женщин быть? И если кто умрет",0,153,0,0],["v","За мужа, разве можно предпочтенье",0,154,0,0],["v","Ему ясней воздать?.. Но это весь",0,155,0,0],["v","Уж город знает… Ты ж послушай лучше",0,155,0,0],["v","И подивись, что было в доме, старец…",0,156,0,0],["v","Когда свой день последний между дней",0,157,0,0],["v","Она узнала, то водой проточной",0,158,0,0],["v","Умыла кожу белую… Потом",0,159,0,0],["v","Из сундука кедрового достала",0,160,0,1],["v","Одежду и убор и убралась",0,160,0,0],["v","Так хорошо. И, став у очага,",0,161,0,0],["v","Взмолилася владычице: \"Богиня,<a class=\"nr\" href=\"#n-k11\" data-n=\"k11\" aria-label=\"Примечание 11\">11</a>",0,162,0,0],["v","Меня Аид в свой темный дом берет.",0,163,0,0],["v","И я теперь в последний раз припала",0,164,0,0],["v","К тебе: храни моих сирот, молю.",0,165,0,0],["v","Ты сыну дай жену по мысли, мужа",0,165,0,0],["v","Дай дочери достойного, и пусть",0,166,0,0],["v","Не так, как мать, без времени, а в счастье,",0,167,0,0],["v","Свершивши путь житейский и вкусив",0,168,0,0],["v","Его услад, в земле почиют отчей\".",0,169,0,0],["v","И сколько есть в чертоге алтарей,",0,170,0,1],["v","Все обошла с молитвой и листвою",0,170,0,0],["v","Венчала их зеленою она",0,171,0,0],["v","И свежею от мирта! Но ни стона,",0,172,0,0],["v","Ни плача бог не принял, и над ней",0,173,0,0],["v","Нависшая гроза не омрачила",0,173,0,0],["v","Ее красы сиянья благородной…",0,174,0,0],["v","От алтарей в венчальный свой покой",0,175,0,0],["v","Она вошла, и здесь, увидев ложе,",0,176,0,0],["v","Заплакала царица и сказала:",0,176,0,0],["v","\"О ложе, ты, что брачный пояс мой",0,177,0,0],["v","Распущенным увидело, — прости!",0,178,0,0],["v","Я не сержусь, хоть только ты сгубило",0,179,0,0],["v","Меня: тебе и мужу изменить",0,180,0,1],["v","Боялась я, и видишь — умираю.",0,180,0,0],["v","Другой жене послужишь ты — она",0,181,0,0],["v","Верней меня не будет, разве только<a class=\"nr\" href=\"#n-k12\" data-n=\"k12\" aria-label=\"Примечание 12\">12</a>",0,182,0,0],["v","Счастливее\". И, на постель припав,",0,183,0,0],["v","Лобзаньями ее царица кроет,",0,184,0,0],["v","И реки слез сбегают на постель.",0,185,0,0],["v","Потом уж ей и плач насытил сердце,",0,185,0,0],["v","А с ложем все расстаться не могла.",0,186,0,0],["v","За дверь уйдет, оглянется и снова",0,187,0,0],["v","И снова в спальню кинется. А тут",0,188,0,0],["v","За пеплос ей цеплялись дети с плачем,",0,189,0,0],["v","И на руки брала <span class=\"ch\" data-ch=\"alkesta\">Алькеста</span> их:",0,190,0,1],["v","То дочь она, то целовала сына,",0,190,0,0],["v","Благословляя их, — и сколько нас",0,191,0,0],["v","В Адметовом чертоге, каждый плакал,",0,192,0,0],["v","Царицу провожая. А она",0,193,0,0],["v","Нам каждому протягивала руку;",0,193,0,0],["v","Последнего поденщика приветом",0,194,0,0],["v","Не обошла, прощаясь, и словам",0,195,0,0],["v","Внимала каждого. Вот повесть зол",0,196,0,0],["v","Адметовых. Когда бы сам он умер,",0,196,0,0],["v","От горя бы ушел он, но, от смерти",0,197,0,0],["v","Спасенный, мук уж не избудет он.",0,198,0,0],["sp","Корифей"],["v","О, сколько слез сегодня им прольется!",0,199,0,0],["v","Легко ль жену такую потерять?",0,200,0,1],["sp","Служанка"],["v","Из рук ее, любимую, не хочет",0,201,0,0],["v","Он выпустить. И на руках его,",0,202,0,0],["v","Томимая недугом, тихо тает",0,203,0,0],["v","<span class=\"ch\" data-ch=\"alkesta\">Алькеста</span> — сил у ней уж больше нет,",0,204,0,0],["v","А все-таки, пока еще дыханье",0,205,0,0],["v","В груди не прекратилось, поглядеть",0,206,0,0],["v","Ей хочется на солнце. Но вернусь<a class=\"nr\" href=\"#n-k13\" data-n=\"k13\" aria-label=\"Примечание 13\">13</a>",0,207,0,0],["v","И расскажу, что ты пришел, владыкам.",0,208,0,0],["v","Увы! не все так близки, чтоб в беде",0,210,0,1],["v","Сочувствие высказывать, — ты ж верный",0,210,0,0],["v","И давний друг моих господ, — я знаю.",0,211,0,0],["sd","(Уходит в дом.)"],["scene","Первый музыкальный антракт","s7",2,7],["sp","Первое полухорие"],["str","Строфа"],["v","Где ж выход, о Зевс, из этого зла, где выход найду я?",0,212,0,0],["v","И царскому дому узла",0,213,0,0],["v","Ужель не развяжешь ты, бог?",0,213,0,0],["sp","Второе полухорие"],["v","Но выйдет ли кто? Не время ль ножу",0,214,0,0],["v","Коснуться волос и черным",0,215,0,0],["v","Мне скорби одеться покровом?",0,216,0,0],["sp","Первое полухорие"],["v","Близок уж, близок конец:",0,216,0,0],["v","Все же молиться, друзья,",0,217,0,0],["v","Будем молиться:",0,218,0,0],["v","Сила безмерна богов.",0,219,0,0],["sp","Хор"],["v","О владыка Пеан,",0,220,0,1],["v","Ты защиту царю обрети.",0,220,0,0],["v","И подай ее, боже, подай…",0,221,0,0],["v","Будь и ныне, Пеан, как тогда,",0,222,0,0],["v","Избавителем наших царей,",0,223,0,0],["v","И да сгибнет кровавый Аид",0,224,0,0],["v","Перед силой твоею, Пеан.",0,225,0,0],["sp","Второе полухорие"],["str","Антистрофа"],["v","Увы!<a class=\"nr\" href=\"#n-k14\" data-n=\"k14\" aria-label=\"Примечание 14\">14</a>",0,225,0,0],["v","Как будет сын <span class=\"ch\" data-ch=\"feret\">Ферета</span> жить?",0,226,0,0],["v","С ним нет благородной жены.",0,227,0,0],["sp","Первое полухорие"],["v","Не нож ли его достойно прервет",0,228,0,0],["v","Удел, иль в воздухе петля",0,229,0,0],["v","Адметову шею обымет?",0,230,0,1],["sp","Второе полухорие"],["v","Не дорогую жену,",0,230,0,0],["v","Ту, коей нету дороже,",0,231,0,0],["v","В день этот тяжкий",0,231,0,0],["v","Мертвой увидит <span class=\"ch\" data-ch=\"admet\">Адмет</span>.",0,232,0,0],["sd","Двери чертога открываются широко, и оттуда показывается шествие. Среди заплаканных, но сдержанных служанок и нескольких старых рабов идет <span class=\"ch\" data-ch=\"admet\">Адмет</span>, он несет на руках <span class=\"ch\" data-ch=\"alkesta\">Алькесту</span>. Позади старый и хромой раб-педагог ведет за руку Евмела и его сестру. В толпе, которая следует за ними, есть жрец и доктор."],["sp","Второе полухорие"],["v","О, гляди же, гляди:",0,233,0,0],["v","Из чертога выходят… идут…",0,233,0,0],["v","О, стенай: возопи, о земля,",0,234,0,0],["v","Вы оплачьте, ферейцы, жену,",0,235,0,0],["v","Что, недугом томимая злым,",0,235,0,0],["v","Из чертогов царя перейдет",0,236,0,0],["v","В подземелье Аидово днесь.",0,236,0,0],["sd","Шествие останавливается на авансцене. Суета. Движение в толпе слуг. Приносят в орхестру низкое ложе. При последних словах хора <span class=\"ch\" data-ch=\"admet\">Адмет</span> осторожно кладет <span class=\"ch\" data-ch=\"alkesta\">Алькесту</span>, бледную и слабую, на ложе и становится в ногах, а служанка в головах царицы. Хоревты приветствуют царскую семью поклонами."],["sp","Хор"],["dir","сдержанно"],["v","Нет, никогда не сочту",0,237,1,0],["v","Радостей брака сильнее",0,238,1,0],["v","Тяжкой его печали.",0,238,1,0],["v","Участь царя <span class=\"ch\" data-ch=\"admet\">Адмета</span>",0,239,1,0],["v","Ярче, чем старый опыт…",0,240,1,1],["v","Как, о, как будет жить он",0,241,1,0],["v","В этих пустых чертогах?",0,242,0,0],["scene","Явление шестое","s8",2,8],["sd","Адмет, Алькеста, дети, свита. Все затихло. Все взоры обращены на <span class=\"ch\" data-ch=\"alkesta\">Алькесту</span>."],["sp","<span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>"],["dir","приподнимаясь на ложе"],["str","Строфа I"],["v","Солнце веселое, здравствуй!",0,243,0,0],["v","В вихре эфирном и ты,",0,244,0,0],["v","Облако вольное, здравствуй!",0,245,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Пусть видит нас обоих несчастливцев:",0,246,0,0],["v","Богов ничем не оскорбили мы.",0,247,0,0],["sp","<span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>"],["str","Антистрофа I"],["v","Ты, о земля, и чертог наш,",0,248,1,0],["v","Девичий терем и ты,",0,249,1,0],["v","Город мой отчий… простите!..",0,250,1,1],["sd","(В изнеможении опускается на ложе.)"],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Приободрись, несчастная, не выдай!..",0,250,0,0],["v","Властителей небесных умоляй!..",0,251,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>"],["dir","с изменившимся от ужаса лицом молчит с минуту, только перебирая губами. Потом поднимает к небу тонкие, белые руки, приподнимается сама, глаза ее расширяются. Она указывает вдаль"],["str","Строфа II"],["v","Уж вот они… вот… на воде…",0,252,0,0],["v","Челнок двухвесельный, и там",0,252,0,0],["v","Меж трупов Харон-перевозчик,",0,253,0,0],["v","На весло налегая, зовет…",0,254,0,0],["v","\"Что медлишь?",0,255,0,0],["v","Что медлишь? — кричит. — Торопись…",0,255,0,0],["v","Тебя только ждем мы… Скорее!\"",0,256,0,0],["v","Из толпы служанок вырывается рыдание.",0,257,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","О, горе нам! Печальный этот путь",0,257,0,0],["v","Зачем себе сулишь? О, горе, горе!",0,258,0,0],["sp","<span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>"],["dir","встает и берет <span class=\"ch\" data-ch=\"admet\">Адмета</span> за руку"],["str","Антистрофа II"],["v","Уводит… Уводит меня.",0,259,0,0],["v","Не видишь ты разве? Туда,",0,260,0,1],["v","Где мертвые… Пламенем синим",0,260,0,0],["v","Сверкают глаза… Он — крылатый.",0,261,0,0],["v","Ай… Что ты?",0,262,0,0],["v","Оставь нас! В какой это путь",0,263,0,0],["v","Меня снаряжаешь?.. Мне страшно…",0,263,0,0],["sd","Рыданья усиливаются, переходя в истерический плач. Плачущих выталкивают, уводят по знаку <span class=\"ch\" data-ch=\"admet\">Адмета</span>."],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","То скорбный путь… О, как теперь он детям",0,264,0,0],["v","И мне тяжел!.. Печаль одна у нас…",0,265,0,0],["sd","Пауза."],["sd","<span class=\"ch\" data-ch=\"alkesta\">Алькеста</span> под влиянием своих болезненных видений покинула ложе. Теперь, когда галлюцинации оставляют ее, ослабелая, она глазами ищет опоры. И наконец, вся бледная, припадает к <span class=\"ch\" data-ch=\"admet\">Адмету</span>, который держит ее прислонив к своей груди и молча ласкает ей волосы. Молчаливая сцена, потом —"],["sp","<span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>"],["dir","тихо"],["str","Эпод"],["v","Оставьте, оставьте… меня…",0,266,0,0],["v","Стоять не могу… Положите…",0,266,0,0],["v","Аид надо мною…",0,267,0,0],["v","Ночь облаком глаза мои покрыла…",0,268,0,0],["v","Внезапная вспышка силы.",0,269,0,0],["v","О, дайте мне детей моих, детей…",0,270,1,1],["sd","(Порывисто ласкает детей, которые с громким плачем прижимаются к ней, сидя на ложе, на которое <span class=\"ch\" data-ch=\"admet\">Адмет</span> ее посадил.)"],["v","Нет матери у вас, нет больше мамы…",0,270,1,0],["v","Прощайте… Пусть вам солнце светит, дети…",0,271,1,0],["sd","(Отстраняя детей, откидывается на ложе.)"],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["dir","склоняясь над нею"],["v","Увы мне! Увы мне… Слова",0,272,0,0],["v","Такие мне смерти больнее…",0,273,0,0],["v","О нет, дорогая, о нет…",0,273,0,0],["v","Ты нас не оставишь…",0,274,0,0],["v","Ну, ради детей…",0,275,0,0],["v","Неужто сирот ты покинешь?",0,276,0,0],["v","О, будь же добрее… Тебя",0,276,0,0],["v","Не станет… и я не жилец ведь,",0,277,0,0],["v","В тебе наша жизнь, наша смерть.",0,278,0,0],["v","Любовь твоя — это алтарь мой.",0,279,0,0],["sp","<span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>"],["dir","мало-помалу приходит в себя и начинает говорить, сначала тихо, с остановками; потом речь идет свободнее"],["v","Еще живу, Адмет… Ты видишь, как?",0,280,0,1],["v","Последнюю пора поведать волю:",0,280,0,0],["v","Я жизнь твою достойнее своей",0,281,0,0],["v","Сочла, Адмет, и чтобы мог ты видеть",0,282,0,0],["v","Лучи небес, я душу отдала.",0,283,0,0],["v","О, жить еще могла бы я и мужа",0,284,0,0],["v","В Фессалии избрать себе по мысли,",0,285,0,0],["v","С ним царский дом и радости делить.",0,286,0,0],["v","Но мне не надо жизни без <span class=\"ch\" data-ch=\"admet\">Адмета</span>",0,287,0,0],["v","С сиротами… И юности услад",0,288,0,0],["v","Я не хочу, с тобой не разделенных…",0,289,0,0],["sd","Пауза."],["v","Отцом и матерью ты предан… А они",0,290,0,1],["v","До старости уж дожили в довольстве,",0,290,0,0],["v","Ты был один у них.",0,291,0,0],["v","И умереть",1,291,0,0],["v","Они могли бы честно, уступивши",0,292,0,0],["v","Тебе сиянье солнца: на других",0,293,0,0],["v","Детей у стариков ведь нет надежды…",0,294,0,0],["v","И я могла бы жить, да и тебе",0,295,0,0],["v","Оплакивать жены б не приходилось,",0,296,0,0],["v","С сиротами вдовея… Видно, так",0,297,0,0],["v","Кто из богов судил… Да будет воля",0,298,0,0],["v","Его… А мне одно ты обещай.",0,299,0,0],["v","О мзде прошу неравной: ведь ценнее,",0,300,0,1],["v","Чем жизни дар, у человека нет…",0,301,0,0],["v","Ты скажешь сам, Адмет, что справедливо",0,302,0,0],["v","Желание мое… Люби детей (лаская детей),",0,303,0,0],["v","Как я люблю их! Ты ж их любишь? Правда?",0,304,0,0],["v","Ведь не безумец ты… О, сохрани",0,305,0,0],["v","Для них мой дом! Ты мачехи к сиротам",0,306,0,0],["v","Не приводи, чтоб в зависти детей",0,307,0,0],["v","Моих она, Адмет, не затолкала,",0,308,0,0],["v","Не запугала слабых… И змея",0,309,0,0],["v","Для пасынков ее не будет злее.",0,310,0,1],["v","Пусть сын в отце защитника найдет.",0,310,0,0],["v","Но ты (привлекает с ласкою дочь), дитя, когда",0,311,0,0],["v","невестой будешь,",0,312,4,0],["v","В жене отца найдешь ли мать? Тебя",0,313,0,0],["v","Убережет ли чистой?.. Доброй славы",0,314,0,0],["v","Твоей не опорочит ли и брак",0,315,0,0],["v","Не сгубит ли надежду целой жизни?",0,315,0,0],["v","Увы! Не мне невестой жениху",0,316,0,0],["v","Тебя вручать, и в муках материнства",0,317,0,0],["v","Не мать тебя поддержит, — а милей",0,318,0,0],["v","Нет никого родимой в этих муках.",0,319,0,0],["sd","Пауза."],["sd","Она молча ласкает дочь. Евмел стоит молча с опущенной головой, вырвав руку у дядьки."],["v","Я умереть должна… И смерть придет",0,320,0,1],["v","Не завтра… мне и дней считать не надо…",0,320,0,0],["v","Минута, и <span class=\"ch\" data-ch=\"alkesta\">Алькесту</span> назовут",0,321,0,0],["v","Средь тех, кто жил…",0,322,0,0],["sd","(Приподнимается и воздевает руки с благословением сначала над <span class=\"ch\" data-ch=\"admet\">Адметом</span>, потом над детьми.)"],["v","Да будет счастье с вами!",0,323,0,0],["v","С тобой, <span class=\"ch\" data-ch=\"admet\">Адмет</span>: ты добрую жену",0,323,0,0],["v","Имел, — гордись. Вы ж, дети, материнской",0,324,0,0],["v","Живите славой, светлы на земле…",0,325,0,0],["sp","Корифей"],["v","Спокойна будь, царица. Если разум",0,326,0,0],["v","В нем есть, жены исполнит волю царь.",0,326,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","О да, о да! Все сделаю, не бойся!",0,327,0,0],["v","Ты мне была женою на земле",0,328,0,0],["v","И под землей схоронишь это имя.",0,329,0,0],["v","Нет, ни одна из фессалийских дев",0,330,0,1],["v","Не назовет меня супругом. Разве",0,330,0,0],["v","Рождением иль красотою кто",0,331,0,0],["v","Из них дерзнет с тобою спорить? Дети —",0,332,0,0],["v","Довольно их с меня. О них богам",0,333,0,0],["v","Молиться мне, коль не сберег тебя я.",0,334,0,0],["v","А по тебе я траур и не год,",0,335,0,0],["v","Всю жизнь носить, Алькеста, буду, сколько",0,336,0,0],["v","Пошлют мне боги дней; отца ж и мать",0,337,0,0],["v","Родимую век ненавидеть буду.",0,338,0,0],["v","Их на словах любовь была, а ты,",0,339,0,0],["v","Ты жертвою великой сберегла",0,340,0,1],["v","Душе моей отрадное дыханье…",0,340,0,0],["v","О, мне ли, мне ль не плакать, потеряв",0,341,0,0],["v","Любовь такой жены?.. Пиры и шутки,",0,342,0,0],["v","Веселый круг друзей забуду я",0,343,0,0],["v","Увенчанных, и Муз, царивших в доме…",0,344,0,0],["v","И никогда до струн уже рукой",0,345,0,0],["v","Я не коснусь… души ливийской флейтой",0,345,0,0],["v","Не облегчу унылой, — ты взяла",0,346,0,0],["v","Из этой жизни радость…",0,347,0,0],["v","Мастерам же",1,347,0,0],["v","Я закажу, чтоб статую твою",0,348,0,0],["v","Мне сделали, и на постель с собою",0,349,0,0],["v","Ее возьму, чтоб ночью обнимать,",0,350,0,1],["v","Звать именем твоим, воображая,",0,350,0,0],["v","Что это ты, Алькеста, что тебя",0,351,0,0],["v","Я к сердцу прижимаю… Это — радость",0,352,0,0],["v","Холодная, конечно, все же сердцу",0,353,0,0],["v","С ней будет легче. В грезах, может быть,",0,354,0,0],["v","Ко мне сойдешь ты, утешая.",0,355,0,0],["v","Сладко",1,355,0,0],["v","Увидеться друзьям, хотя бы в сонном",0,355,0,0],["v","Мечтании, и каждая минута",0,356,0,0],["v","Им дорога свидания. О, если б",0,357,0,0],["v","Орфея мне слова и голос нежный,",0,358,0,0],["v","Чтоб умолить я Персефону мог",0,359,0,0],["v","И, гимнами Аида услаждая,",0,360,1,1],["v","Тебя вернуть. Клянусь, ни Кербер адский,",0,360,0,0],["v","Ни на весло налегший там Харон",0,361,0,0],["v","Желаний бы во мне не охладили,",0,362,0,0],["v","Пока б тебя я солнцу не вернул…",0,363,0,0],["sd","Пауза. <span class=\"ch\" data-ch=\"admet\">Адмет</span> ласкает волосы <span class=\"ch\" data-ch=\"alkesta\">Алькесты</span>. <span class=\"ch\" data-ch=\"alkesta\">Алькеста</span> все время лежала с закрытыми глазами. Она закрыла их после того, как <span class=\"ch\" data-ch=\"admet\">Адмет</span> перестал говорить о детях. Теперь она снова их открывает."],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["dir","после слез, с которыми он справился"],["v","Ты будешь ждать меня? Не так ли? Дом ты",0,363,0,0],["v","Для нас там приготовишь, чтоб его",0,364,0,0],["v","Делить со мной, когда умру? А в мире",0,365,0,0],["v","В один кедровый гроб похоронить",0,366,0,0],["v","Обоих нас велю я. С милой рядом",0,366,0,0],["v","В нем лягу я, и смерть не разлучит",0,367,0,0],["v","С подругою меня неизменившей…",0,368,0,0],["sp","Корифей"],["v","И я с тобой покойную, и я",0,369,0,0],["v","Оплачу, царь: она достойна плача.",0,370,0,1],["sp","<span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>"],["dir","к детям"],["v","Вы слышали, о дети, ваш отец",0,370,0,0],["v","Не женится. Он женщине над вами",0,371,0,0],["v","Чужой не даст хозяйничать — меня",0,372,0,0],["v","Не обесчестит он, — он обещал мне…",0,373,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","И повторю: я выполню, о да!..",0,374,0,0],["sp","<span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>"],["dir","<span class=\"ch\" data-ch=\"admet\">Адмету</span>"],["v","Детей из рук моих прими — я верю.",0,375,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["dir","обнимая детей"],["v","О! Милый дар и из любимых рук.",0,376,0,0],["sp","<span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>"],["v","Ты замени им мать отныне, бедным.",0,377,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Придется быть… без матери… за мать.",0,378,0,0],["sp","<span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>"],["v","О дети, жить хочу… Темна могила.",0,379,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","А я, увы! Как буду жить… теперь?",0,380,0,1],["sp","<span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>"],["v","Года залечат рану, — что нам мертвый?",0,381,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["dir","с возрастающим чувством"],["v","Возьми меня с собой, молю, возьми…",0,382,0,0],["sp","<span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>"],["v","Довольно с них одной меня, с подземных.",0,383,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Кого от нас, кого берешь ты, бог!",0,384,0,0],["sp","<span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>"],["dir","ложится и больше уже не приподнимается"],["v","Глаза мои под игом ночи тяжкой…",0,385,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Погиб тобой покинутый, погиб…",0,386,0,0],["sp","<span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>"],["v","Меня уж нет… Ничто я… Нет <span class=\"ch\" data-ch=\"alkesta\">Алькесты</span>.",0,387,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Приподними лицо, хоть для детей.",0,388,0,0],["sp","<span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>"],["v","Я не могу, <span class=\"ch\" data-ch=\"admet\">Адмет</span>. Прощайте, дети!",0,389,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Взгляни на них, взгляни…",0,390,0,1],["sp","<span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>"],["v","<span class=\"ch\" data-ch=\"alkesta\">Алькесты</span> нет.",1,390,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Что делаешь? Уходишь?",0,390,0,0],["sp","<span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>"],["v","Да.",1,390,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","О, горе!",1,390,0,0],["sp","Корифей"],["v","Нет меж живых Адметовой жены.",0,391,0,0],["sd","Минутная пауза. Все молча склоняются перед <span class=\"ch\" data-ch=\"alkesta\">Алькестой</span>. <span class=\"ch\" data-ch=\"admet\">Адмет</span> закрыл лицо руками. Молчание прерывает Евмел, порывисто бросаясь к телу матери."],["sp","Евмел"],["str","Строфа"],["v","Горе, о, горе мое!",0,392,3,0],["v","В землю родная ушла.",0,393,3,0],["v","В темной могиле, отец,",0,393,3,0],["v","Солнцу ее не согреть.",0,394,3,0],["v","Сыну ж зачем сиротой,",0,395,3,0],["v","Злая, велела ты жить?",0,396,3,0],["sd","(К отцу.)"],["v","О, посмотри на нее:",0,396,3,0],["v","Веки запали, и рук",0,397,3,0],["v","Страшен холодный покой.",0,398,3,0],["sd","(Снова к матери, тихо касаясь ее руки.)"],["v","Мать, послушай меня,",0,399,3,0],["v","Сына послушай, молю.",0,400,3,1],["sd","(Целуя ее.)"],["v","Это к холодным губам",0,400,3,0],["v","Твой детеныш припал.",0,401,3,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Не слышит нас она, не видит, дети…",0,402,0,0],["v","Мы тяжкою поражены бедой.",0,403,0,0],["sp","Евмел"],["dir","приближаясь к отцу"],["str","Антистрофа"],["v","Рано я стану, отец,",0,404,0,0],["v","В доме твоем сиротой,",0,405,0,0],["v","Я ведь один у тебя…",0,406,0,0],["v","Сколько я видел уже",0,407,0,0],["v","Страшного в жизни, отец.",0,408,0,0],["sd","(Прижимается к нему и рукой ищет взять руку сестры, которая молча смотрит на мать.)"],["v","Бедствия вместе со мной",0,409,0,0],["v","Ты выносила, сестра,",0,410,0,1],["v","О, не на радость себе",0,410,0,0],["v","Сватал жену ты, отец;",0,411,0,0],["v","Старости вместе достичь",0,412,0,0],["v","Вам не пришлось, и теперь",0,413,0,0],["v","С той, что покинула нас,",0,414,0,0],["v","Гибнет старинный наш дом.<a class=\"nr\" href=\"#n-k15\" data-n=\"k15\" aria-label=\"Примечание 15\">15</a>",0,415,0,0],["sp","Корифей"],["dir","подходя к <span class=\"ch\" data-ch=\"admet\">Адмету</span>"],["v","Адмет, терпеть злосчастье нам неволя:",0,416,0,0],["v","Не первый ты и не последний ты",0,417,0,0],["v","Достойнейшей лишаешься супруги:",0,418,0,0],["v","Держи в уме, что мы и все умрем.",0,419,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["dir","с достоинством"],["v","О, это зло обрушилось не сразу.",0,420,0,1],["v","Я знал о нем и раньше и давно.",0,420,0,0],["v","Терзался я, к нему готовя мысли.",0,421,0,0],["v","Но мертвой мне устроить вынос надо,",0,422,0,0],["v","Останьтесь здесь. И богу адских сил",0,423,0,0],["v","Сухой пеан воспойте, чередуясь.<a class=\"nr\" href=\"#n-k16\" data-n=\"k16\" aria-label=\"Примечание 16\">16</a>",0,424,0,0],["sd","(Обращаясь к окружающим, причем слуги отступают.)"],["v","Я подданных в Фессалии моих",0,425,0,0],["v","Сим разделить прошу со мною траур:",0,426,0,0],["v","Отрежьте кудри, черное наденьте,",0,427,0,0],["v","Четверкам же и одиночкам гривы",0,428,0,0],["v","Прошу скосить железом, — и ни флейт,",0,429,0,0],["v","Ни лиры шум да не наполнит улиц,",0,430,0,1],["v","Двенадцать лун покуда протечет…<a class=\"nr\" href=\"#n-k17\" data-n=\"k17\" aria-label=\"Примечание 17\">17</a>",0,431,0,0],["v","Покойника милее не придется",0,432,0,0],["v","Мне хоронить… Не заслужил никто",0,433,0,0],["v","Передо мной почета высшей жертвой.",0,434,0,0],["sd","Слуги наскоро обряжают покойницу. <span class=\"ch\" data-ch=\"admet\">Адмет</span> уходит в дом."],["scene","Второй музыкальный антракт","s9",2,9],["str","Строфа I"],["v","О Пелиада, радость",0,435,0,0],["v","В дом принеси Аида,",0,436,0,0],["v","Лика не зревший солнца,",0,437,0,0],["v","Ты же, Аид черновласый,",0,438,0,0],["v","Бог и старый кормчий,",0,440,0,1],["v","Мертвых в ладье еловой",0,441,0,0],["v","Тяжким веслом влекущий,",0,442,0,0],["v","Знайте: волна Ахеронта",0,443,0,0],["v","Лучшей жены не видала.",0,444,0,0],["str","Антистрофа I"],["v","Часто тебя любимцы",0,445,0,0],["v","Муз семиструнной лирой,",0,446,0,0],["v","Часто безлирным гимном",0,447,0,0],["v","В Спарте восславят в Карнейский",0,448,0,0],["v","Ярко-лунный месяц.<a class=\"nr\" href=\"#n-k18\" data-n=\"k18\" aria-label=\"Примечание 18\">18</a>",0,450,0,1],["v","Будут тебя и Афины",0,451,0,0],["v","Ясноблаженные славить.",0,452,0,0],["v","Сколько певцам благородных",0,453,0,0],["v","Песен <span class=\"ch\" data-ch=\"alkesta\">Алькеста</span> оставит!",0,454,0,0],["str","Строфа II"],["v","О, если бы мог я, о боги!",0,455,0,0],["v","К свету вернуть царицу",0,456,0,0],["v","Из теремов Аида,",0,457,0,0],["v","От стонущих струй Кокита.<a class=\"nr\" href=\"#n-k19\" data-n=\"k19\" aria-label=\"Примечание 19\">19</a>",0,458,0,0],["v","Нет тебе равной в женах,",0,460,0,1],["v","Нет той любви больше,",0,460,0,0],["v","Если в юдоль мрака,",0,461,0,0],["v","Мужа сменив, сойдешь ты…",0,462,0,0],["v","Да будет легка над тобою",0,462,0,0],["v","Земля, царица, а муж твой,",0,463,0,0],["v","Коль ложе возьмет иное, —",0,464,0,0],["v","Как детям твоим, он будет",0,464,0,0],["v","И нам всегда ненавистен.",0,465,0,0],["str","Антистрофа II"],["v","Ни матери не было воли",0,466,0,0],["v","Сына спасти, в землю",0,466,0,0],["v","Кости свои сложивши,",0,467,0,0],["v","Ни воли на то отцовской",0,468,0,0],["v","Смертью спасти родного.",0,468,0,0],["v","А ведь как лунь седы.",0,469,0,0],["v","Ты же, как цвет вешний,",0,470,0,1],["v","В землю пошла за мужа.",0,470,0,0],["v","Вот если б такою подругой",0,471,0,0],["v","Украсить мог бы я век свой.",0,472,0,0],["v","Увы! То не частая доля,",0,473,0,0],["v","Не знали бы с ней мы горя,",0,474,0,0],["v","Покуда бы дни делили.",0,475,0,0],["act","Действие второе","a3","II"],["scene","Явление седьмое","s10",3,10],["sd","Со стороны чужестранцев входит <span class=\"ch\" data-ch=\"gerakl\">Геракл</span>. Львиная шкура, палица и лук с колчаном. Он не сходит в орхестру."],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Почтенному ферейскому гражданству…",0,475,0,0],["v","Застану ль я <span class=\"ch\" data-ch=\"admet\">Адмета</span> во дворце?",0,476,0,0],["v","Обмениваются поклонами.",0,477,0,0],["sp","Корифей"],["v","Он дома, сын <span class=\"ch\" data-ch=\"feret\">Феретов</span>. У <span class=\"ch\" data-ch=\"gerakl\">Геракла</span> ж",0,478,0,0],["v","В Фессалии, конечно, дело есть,",0,479,0,0],["v","Коль к городу ферейскому подходит?",0,480,0,1],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Да, от царя тиринфского наказ.",0,480,0,0],["sp","Корифей"],["v","Куда ж, Геракл, в какой ты путь снаряжен?",0,481,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","За четверней иду я, что царю",0,482,0,0],["v","Фракийскому покорна, Диомеду.",0,483,0,0],["sp","Корифей"],["v","Но как возьмешь? Скажи, фракийца знаешь?",0,484,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Нет, не видал. В стране бистонской нам<a class=\"nr\" href=\"#n-k20\" data-n=\"k20\" aria-label=\"Примечание 20\">20</a>",0,485,0,0],["v","Еще побыть не доводилось, люди.",0,486,0,0],["sp","Корифей"],["v","Без боя там коней тебе не взять.",0,487,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Но как же мне от дела отказаться?",0,488,0,0],["sp","Корифей"],["v","Убьешь его иль мертвый ляжешь сам…",0,489,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Не в первый раз в глаза глядеть и смерти.",0,490,0,1],["sp","Корифей"],["v","Но и царя убьешь… Что пользы в том?",0,490,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Его коней отдам я Еврисфею.",0,491,0,0],["sp","Корифей"],["v","Узду на них накинуть не легко.",0,492,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Не пламенем они ж, надеюсь, дышат?",0,493,0,0],["sp","Корифей"],["v","Их челюсти жуют мужей, <span class=\"ch\" data-ch=\"gerakl\">Геракл</span>.",0,494,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["dir","с недоверием"],["v","О хищниках ты говоришь нам горных?",0,495,0,0],["sp","Корифей"],["v","Я говорю о стойлах их, герой;",0,495,0,0],["v","Увидишь сам: они покрыты кровью.",0,496,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Но чей же сын их вырастил, скажи?",0,497,0,0],["sp","Корифей"],["v","Арея сын, златых щитов державец.",0,498,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Да, такова судьба моя, — суров",0,499,0,0],["v","<span class=\"ch\" data-ch=\"gerakl\">Геракла</span> путь, все круче путь мой тяжкий.",0,500,0,1],["v","Ужели ж бой со всеми на роду",0,500,0,0],["v","Написан мне, рожденными Ареем?",0,501,0,0],["v","То Ликаон, то Кикн, а вот еще<a class=\"nr\" href=\"#n-k21\" data-n=\"k21\" aria-label=\"Примечание 21\">21</a>",0,502,0,0],["v","И третий сын, коневладыка этот,",0,503,0,0],["v","Которого я должен одолеть.",0,504,0,0],["v","Но не видать лучам, чтоб сын Алкмены",0,505,0,0],["v","От вражеской десницы убегал…",0,506,0,0],["scene","Явление восьмое","s11",3,11],["sd","Те же и <span class=\"ch\" data-ch=\"admet\">Адмет</span>, в трауре, обритый, заплаканный."],["sp","Корифей"],["v","А вот и сам хозяин, из чертога",0,507,0,0],["v","Выходит царь <span class=\"ch\" data-ch=\"admet\">Адмет</span>, наш повелитель.",0,508,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["dir","кланяясь <span class=\"ch\" data-ch=\"gerakl\">Гераклу</span>"],["v","О, радуйся, сын Зевса, Персеид.<a class=\"nr\" href=\"#n-k22\" data-n=\"k22\" aria-label=\"Примечание 22\">22</a>",0,509,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["dir","возвращая поклон"],["v","Ты радуйся, владыка фессалийский!",0,510,0,1],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","О, пусть бы так, товарищ, пусть бы так.",0,511,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["dir","оглядывая его"],["v","Ты в трауре… Острижен… Что причиной?",0,512,0,0],["sd","Небольшая пауза."],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["dir","собравшись с силами"],["v","Сегодня мне придется хоронить…",0,513,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Не из детей кого? Избави боже…",0,514,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Рожденные <span class=\"ch\" data-ch=\"admet\">Адметом</span> живы все.",0,515,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Отец для смерти зрелый… Уж не он ли?",0,516,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","И он, и мать моя еще живут.",0,517,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Но не жена, конечно ж, не <span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>.",0,518,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["dir","с усилием"],["v","Я надвое могу сказать о ней.",0,519,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Жива она иль умерла, скажи мне?",0,520,0,1],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Жива и нет — печалит — это так…",0,521,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["dir","подумав"],["v","Я ничего из слов твоих не понял.",0,522,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["dir","помолчав"],["v","Ты о судьбе ее, скажи, слыхал?",0,523,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Что за тебя на смерть решилась? Слышал.",0,524,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Тогда могу ль сказать: «Она живет»?",0,525,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Оплакивать как будто все же рано.",0,526,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Кто смерть принять готов, уж не жилец.",0,527,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Но быть или не быть одно ль и то же?",0,528,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Ты судишь так, я иначе, герой.",0,529,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Но плачешь ты? Иль ты утратил друга?",0,530,0,1],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Жену, Геракл, и только что притом.",0,530,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Она была чужая иль из кровных?",0,530,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Чужая, да! Но близкая семье.",0,530,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Но здесь, у вас, как дни пришлось ей кончить?",0,530,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Нам от отца досталась сиротой.",0,530,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Ты в трауре… Мне очень жаль, Адмет…",0,530,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["dir","с живостью"],["v","К чему, скажи, ты эту речь склоняешь?",0,530,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Пойду искать другого очага.",0,530,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","О, это — нет… Недоставало горя…",0,530,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Печальному, Адмет, не сладок гость.",0,530,0,1],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Усопшему — земля, а дом — для друга…",0,531,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Средь плачущих зазорно пировать…",0,532,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Покой тебе особый отведу.",0,533,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Уйти мне дай — навек меня обяжешь…",0,534,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Нет, не бывать тому, чтоб очага",0,535,0,0],["v","Ты шел искать другого.",0,536,0,0],["sd","(Слуге.)"],["v","Чужестранца",0,537,4,0],["v","На тот конец проводишь, дальний зал",0,538,0,0],["v","Ему открыв гостиный, ты прикажешь",0,539,0,0],["v","Служителям пришельца угостить",0,540,0,0],["v","По-царски, раб. Да двери затворите",0,541,0,0],["v","Срединные. Стенанья портят пир,",0,542,0,0],["v","А огорчать не подобает гостя…",0,550,0,1],["sd","Раб сначала идет вперед неохотно, но под влиянием строгого взгляда <span class=\"ch\" data-ch=\"admet\">Адмета</span>, забежав вперед, с поклоном открывает <span class=\"ch\" data-ch=\"gerakl\">Гераклу</span> двери."],["scene","Явление девятое","s12",3,12],["sd","Без <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>."],["sp","Корифей"],["v","Что ты творишь, Адмет? В такой беде",0,550,0,0],["v","И принимать гостей — ты помешался?",0,551,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["dir","без злобы, но нетерпеливо"],["v","Спрошу и я: а прогонять гостей",0,552,0,0],["v","Из дома и из города похвальней?",0,553,0,0],["v","Иль, может быть, тем горе облегчу,",0,554,0,0],["v","Что я к гостям черствее сердцем буду",0,555,0,0],["v","И к бедствию домашнему придам",0,556,0,0],["v","Молву о том, что в Ферах нравы дики?",0,557,0,0],["v","Небось судьба в безводную когда",0,558,0,0],["v","Меня страну аргосскую приводит,",0,559,0,0],["v","Мне ласковый хозяин тоже мил.<a class=\"nr\" href=\"#n-k23\" data-n=\"k23\" aria-label=\"Примечание 23\">23</a>",0,560,0,1],["sp","Корифей"],["v","Но для чего ж, коль это друг надежный,",0,561,0,0],["v","От пришлеца ты горе утаил?",0,562,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Как для чего? Да если б бед моих",0,563,0,0],["v","Хоть часть он знал, ужели б он порога",0,564,0,0],["v","Переступил черту? Я знаю сам,",0,565,0,0],["v","Что он безумным так же, как и ты,",0,566,0,0],["v","Меня бы счел, но дом <span class=\"ch\" data-ch=\"admet\">Адметов</span> гостя",0,567,0,0],["v","Ни выживать, ни оскорблять не даст.",0,568,0,0],["sd","(Поспешно входит в дом.)"],["scene","Третий музыкальный антракт","s13",3,13],["sp","Хор"],["str","Строфа I"],["v","Слава, слава тебе, о свободных мужей чертог открытый!",0,569,0,0],["v","Лиры нежно звучащей царь,<a class=\"nr\" href=\"#n-k24\" data-n=\"k24\" aria-label=\"Примечание 24\">24</a>",0,570,1,1],["v","Сам тебя бог юдолью,",0,571,1,0],["v","Бог избрал пифийский…",0,572,1,0],["v","Здесь он, овцехранитель,",0,573,1,0],["v","Пастырь меж скалоизломов,",0,574,1,0],["v","Тешил тебя свирелью,",0,575,1,0],["v","Стадо на луг сзывая.",0,576,1,0],["str","Антистрофа I"],["v","Чар мелодии ждали пятнистые рыси там, .",0,577,0,0],["v","Офрис горный кидали львы;<a class=\"nr\" href=\"#n-k25\" data-n=\"k25\" aria-label=\"Примечание 25\">25</a>",0,580,1,1],["v","Грив золотых султаны",0,581,1,0],["v","Мерно к тебе склонялись.",0,582,1,0],["v","Чащу елей зеленых",0,583,1,0],["v","Пестрая лань покидала,",0,584,1,0],["v","Звукам свирели рада,",0,585,1,0],["v","Робкая, здесь резвилась.",0,586,1,0],["str","Строфа II"],["v","Где овец бессчетных поят",0,587,0,0],["v","Волны светлые Бебиды,<a class=\"nr\" href=\"#n-k26\" data-n=\"k26\" aria-label=\"Примечание 26\">26</a>",0,590,0,1],["v","И до тех пределов дальних,",0,590,0,0],["v","Где в эфирный мрак на отдых",0,591,0,0],["v","Ставит Гелиос усталых,",0,592,0,0],["v","Заморившихся коней, —",0,592,0,0],["v","Что ни вспаханное поле,",0,593,0,0],["v","Что ни тучный луг зеленый",0,594,0,0],["v","От Молосского предела<a class=\"nr\" href=\"#n-k27\" data-n=\"k27\" aria-label=\"Примечание 27\">27</a>",0,595,0,0],["v","До Эгейского прибрежья,",0,595,0,0],["v","Где ладьи не знают волны,",0,596,0,0],["v","Где царит высокий Пелий, —",0,597,0,0],["v","Все — Адметово наследье.",0,597,0,0],["str","Антистрофа II"],["v","И теперь пред гостем дальним",0,598,0,0],["v","Распахнул он двери дома,",0,599,0,0],["v","Хоть туманятся слезами",0,600,1,1],["v","Над покойницей недавней,",0,600,0,0],["v","Над <span class=\"ch\" data-ch=\"alkesta\">Алькестой</span>, сердцу милой,",0,601,0,0],["v","Очи светлые царя.",0,601,0,0],["v","Благородный дух и в горе",0,602,0,0],["v","Чести голосу послушен.",0,603,0,0],["v","Будьте добрыми — и мудрость",0,603,0,0],["v","Вы найдете. Я дивлюся,",0,604,0,0],["v","И надежда в сердце крепнет,",0,605,0,0],["v","Что богов служитель верный",0,605,0,0],["v","От богов заслужит милость.",0,606,0,0],["act","Действие третье","a4","III"],["scene","Явление десятое","s14",4,14],["sd","<span class=\"ch\" data-ch=\"admet\">Адмет</span> в сопровождении траурной свиты показывается в дверях. Обращаясь к хору и толпе фессалийцев, он отходит к дверям, которые широко раскрываются для ожидаемой процессии, но не сходит в орхестру."],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["dir","с приветом, полным царского достоинства"],["v","Мужи ферейские! Вы все, кого",0,606,0,0],["v","Сочувствие сзывает к скорби нашей!",0,607,0,0],["v","Покойницу убрали и сейчас",0,608,0,0],["v","Ее несут в могилу. Чтя обычай,",0,608,0,0],["v","Последнее скажите ей «прости»",0,609,0,0],["v","Перед ее последнею дорогой.",0,610,0,1],["v","Хор молча кланяется. Пауза.",0,610,0,0],["sp","Корифей"],["dir","к <span class=\"ch\" data-ch=\"admet\">Адмету</span>"],["v","Но посмотри — дрожащею стопой",0,611,0,0],["v","Сюда отец спешит твой. Следом свита",0,612,0,0],["v","Убор несет, усладу мертвецов.",0,613,0,0],["scene","Явление одиннадцатое","s15",4,15],["sd","<span class=\"ch\" data-ch=\"feret\">Ферет</span> в сопровождении небольшой траурной свиты и сам в глубоком трауре и выбритый приходит с домашней стороны. Слуги несут благовония, белую тонкую фату и ожерелье. <span class=\"ch\" data-ch=\"admet\">Адмет</span> выжидает молча, не кланяясь и не делая ни шага навстречу."],["sp","<span class=\"ch\" data-ch=\"feret\">Ферет</span>"],["v","Делить печаль твою, дитя, пришел я.",0,613,0,0],["v","Покойница — возможны ль споры тут? —",0,614,0,0],["v","Была женой примерной, ты супруги",0,615,0,0],["v","Лишился целомудренной. Увы,",0,616,0,0],["v","Рабам судьбы не сбить упорством ига…",0,616,0,0],["v","Прими убор",0,617,0,0],["sd","Рабы подносят <span class=\"ch\" data-ch=\"admet\">Адмету</span> дары по знаку <span class=\"ch\" data-ch=\"feret\">Ферета</span>. <span class=\"ch\" data-ch=\"admet\">Адмет</span> стоит, молча опустив руки."],["v","вот этот — пусть идет",1,617,0,0],["v","С усопшей в могилу. Как же праха",0,618,0,0],["v","Той не почтить, которая твою",0,619,0,0],["v","Ценою дней своих нам жизнь купила,",0,620,0,1],["v","Дитя мое, которая дала",0,620,0,0],["v","Остаток дней и мне прожить спокойно",0,621,0,0],["v","В сознании, что я — отец? Средь жен",0,622,0,0],["v","Славнейшее она оставит имя…",0,623,0,0],["sd","<span class=\"ch\" data-ch=\"admet\">Адмет</span> знаком отклоняет дары. В это время из ворот показывается процессия с высоко поднятыми носилками, где лежит мертвая <span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>. Слышатся рыдания. Хоревты и слуги простирают руки навстречу <span class=\"ch\" data-ch=\"alkesta\">Алькесте</span>, <span class=\"ch\" data-ch=\"feret\">Ферет</span> делает несколько шагов по направлению навстречу телу, но по знаку <span class=\"ch\" data-ch=\"admet\">Адмета</span> слуги ставят тело <span class=\"ch\" data-ch=\"alkesta\">Алькесты</span> в отдалении от старика."],["sp","<span class=\"ch\" data-ch=\"feret\">Ферет</span>"],["dir","издали обращаясь к телу"],["v","О спасшая <span class=\"ch\" data-ch=\"admet\">Адмета</span> и его",0,624,0,0],["v","Родителей подъявшая из праха,",0,625,0,0],["v","Привет тебе! Да благо снизойдет",0,625,0,0],["v","На дивную в Аидовом чертоге.",0,626,0,0],["sd","(Склоняется глубоко и рукою касается земли; потом, поднявшись, к хору.)"],["v","Сокровище — в подобных: на иной,",0,627,0,0],["v","Поверьте мне, не стоит и жениться…",0,628,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["dir","заступая тело <span class=\"ch\" data-ch=\"alkesta\">Алькесты</span>"],["v","Незваный гость на скорбном торжестве,",0,629,0,0],["v","Среди друзей считать тебя не смею, —",0,630,0,1],["v","Возьми назад убор свой. Никогда",0,630,0,0],["v","С покойницей он не сойдет в могилу.",0,631,0,0],["v","С сочувствием ты опоздал. Когда",0,632,0,0],["v","Над головой висела смерть моею,",0,632,0,0],["v","Ты не пришел, старик, ты пожалел",0,633,0,0],["v","Остатком дней пожертвовать.",0,634,0,0],["v","Зачем же",1,634,0,0],["v","Над юностью, загубленной тобою,",0,634,0,0],["v","Теперь приходишь плакать? Обличен",0,635,0,0],["v","Перед людьми достаточно, едва ли",0,636,0,0],["v","Ты даже был моим отцом, старик {*}.<a class=\"nr\" href=\"#n-k28\" data-n=\"k28\" aria-label=\"Примечание 28\">28</a>",0,636,0,0],["v","{* Едва ль и та, что матерью слывет,",0,637,0,0],["v","Родами похваляясь, в самом деле",0,638,0,0],["v","Мне мать; дитя рабыни назвала",0,638,0,0],["v","Своим она и приняла на лоно.}",0,639,0,0],["v","О, средь мужей запятнан ты навеки",0,640,0,1],["v","Бездушием отныне. Осушить",0,641,0,0],["v","Свой кубок и жалеть последней капли,",0,642,0,0],["v","Чтобы спасти родного сына… Да,",0,643,0,0],["v","Вы с матерью дозволили спокойно",0,644,0,0],["v","Чужой жене вас заменить. Так пусть",0,645,0,0],["v","Отца и мать в ней хороню сегодня.",0,646,0,0],["sd","Пауза."],["v","Твой век так мал уж был. Какой бы мог",0,650,0,1],["v","Ты совершить своею жертвой подвиг,",0,651,0,0],["v","Приобрести какую славу…",0,652,0,0],["v","Здесь",1,652,0,0],["v","Ты испытал все счастье человека:",0,653,0,0],["v","От молодых ногтей ты был царем,",0,654,0,0],["v","Наследника имел ты. За тобою",0,655,0,0],["v","Все не пошло бы прахом. Не дерзнешь",0,656,0,0],["v","Ты утверждать, конечно, чтобы старость",0,657,0,0],["v","Я оскорблял твою, что не был я",0,658,0,0],["v","Почтителен. О, за мои заботы",0,660,0,1],["v","Вы с матерью мне заплатили щедро…",0,660,0,0],["v","Поторопись, пожалуйста, родить",0,661,1,0],["v","Еще детей, старик, не то кто будет",0,662,0,0],["v","Тебя кормить и, если наконец",0,663,0,0],["v","Умрешь, твой труп кто уберет, кто вынос",0,664,0,0],["v","Устроит твой? Не я же, не <span class=\"ch\" data-ch=\"admet\">Адмет</span>…",0,665,0,0],["v","Он для тебя давно в земле. И если",0,666,0,0],["v","Еще он видит солнце, то кормильцем",0,667,0,0],["v","И сыном быть обязан не тебе…",0,668,0,0],["v","О, старики так часто смерти просят,",0,669,1,0],["v","А стоит ей приблизиться — никто",0,670,0,1],["v","Уж умирать не хочет. Старость тотчас",0,671,0,0],["v","Становится отрадною для них.",0,672,0,0],["sp","Корифей"],["v","Ну, будет же. Как будто мало горя",0,673,0,0],["v","Того, что есть, — не раздражай отца!",0,674,0,0],["sp","<span class=\"ch\" data-ch=\"feret\">Ферет</span>"],["dir","после некоторого промедления, когда он, по-видимому, борется сам с охватившим его волнением"],["v","Но что за тон, мой сын! Себе лидийца",0,675,0,0],["v","Иль ты раба фригийского купил?",0,676,0,0],["v","Советую припомнить: фессалиец,",0,677,0,0],["v","Свободный сын свободного отца",0,678,0,0],["v","Перед тобой. Слова ж твои ребячьи",0,679,0,0],["v","Меня задеть не могут. Я родил",0,680,0,1],["v","И воспитал тебя, чтоб дом отцовский",0,680,0,0],["v","Тебе отдать, а вовсе не затем,",0,681,0,0],["v","Чтоб выкупать тебя у смерти жизнью.",0,682,0,0],["v","Обычая между отцовских я",0,682,0,0],["v","Такого не припомню и как эллин",0,683,0,0],["v","Всегда считал, что, счастлив кто иль нет, —",0,684,0,0],["v","Таков удел его.",0,684,0,0],["v","Мой долг исполнен:",1,684,0,0],["v","Над многими ты царь, твои поля",0,685,0,0],["v","Умножились. Отцовское оставлю",0,686,0,0],["v","Я полностью <span class=\"ch\" data-ch=\"admet\">Адмету</span>. Чем, скажи,",0,686,0,0],["v","Обижен ты? Чего лишил тебя я?",0,687,0,0],["v","Просил ли я, чтоб ты заменой был",0,688,0,0],["v","Мне в доме том бессолнечном? Нимало.",0,688,0,0],["v","И ты меня о том же не проси.",0,689,0,0],["v","Сам любишь жизнь ты, кажется. В отце",0,690,0,1],["v","Зачем признать любви не хочешь той же?",0,690,0,0],["sd","Пауза."],["v","А право, как подумаешь, что век",0,691,1,0],["v","В земле лежать, так этот промежуток",0,692,0,0],["v","Короткий здесь еще дороже станет…",0,693,0,0],["v","Тебя ль учить мне, впрочем? За него",0,694,0,0],["v","В борьбе с судьбой <span class=\"ch\" data-ch=\"admet\">Адмет</span>, ожесточившись,",0,695,0,0],["v","Не пощадил жены… Но как же он",0,695,0,0],["v","Клянет мою, своей не видя, трусость,",0,696,0,0],["v","Во цвете лет женою побежден.",0,697,0,0],["v","Придумано отлично… хоть и вовсе",0,698,1,0],["v","Не умирай, сменяя верных жен…",0,699,0,0],["v","И у тебя других хватает духа",0,700,0,1],["v","За то, в чем сам виновен, упрекать.",0,701,0,0],["v","Молчи, дитя: жизнелюбивы все мы…",0,702,0,0],["v","На брань твою — вот строгий мой ответ.",0,703,0,0],["sp","Корифей"],["v","Отец и сын, вы перешли границу.",0,704,0,0],["v","Но перестань, старик, его бранить.",0,705,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Пусть говорит; отвечу я: коль правдой",0,706,0,0],["v","Затронут он, зачем топтал ее?",0,710,0,1],["sp","<span class=\"ch\" data-ch=\"feret\">Ферет</span>"],["v","Я б растоптал ее, коль точно б жизнью",0,710,0,0],["v","Своей купил тебе я жизнь, <span class=\"ch\" data-ch=\"admet\">Адмет</span>.",0,711,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Смерть старика и юноши равны ли?",0,712,0,0],["sp","<span class=\"ch\" data-ch=\"feret\">Ферет</span>"],["v","Жить всем нам раз приходится, не дважды.",0,713,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Переживи ж хоть Зевса, коли так…",0,713,0,0],["sp","<span class=\"ch\" data-ch=\"feret\">Ферет</span>"],["v","Но клясть отца за что же, не пойму я.",0,714,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","В тебе желанье жизни — это все.",0,715,0,0],["sp","<span class=\"ch\" data-ch=\"feret\">Ферет</span>"],["dir","указывая на носилки, строго"],["v","А там кого ж <span class=\"ch\" data-ch=\"alkesta\">Алькеста</span> заменила?",0,716,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Ты видишь там свою вину, старик.",0,716,0,0],["sp","<span class=\"ch\" data-ch=\"feret\">Ферет</span>"],["v","Иль за меня ее хоронят, скажешь?",0,717,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Увы! Увы!",0,718,0,0],["sd","(в сторону)"],["v","Когда б нужда ему во мне пришла.",0,719,0,0],["sp","<span class=\"ch\" data-ch=\"feret\">Ферет</span>"],["v","Почаще жен меняй, целее будешь.",0,720,0,1],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Тебе ж стыдней. Зачем себя щадил?",0,721,0,0],["sp","<span class=\"ch\" data-ch=\"feret\">Ферет</span>"],["v","О, этот факел бога так прекрасен.",0,722,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","И это муж? Позор среди мужей…",0,723,0,0],["sp","<span class=\"ch\" data-ch=\"feret\">Ферет</span>"],["v","Ты в гроб меня насмешкой не уложишь.",0,724,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Но славы смерть тебе не принесет.",0,725,0,0],["sp","<span class=\"ch\" data-ch=\"feret\">Ферет</span>"],["v","До мертвого бесславье не доходит.",0,726,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Такой старик… И хоть бы тень стыда…",0,727,0,0],["sp","<span class=\"ch\" data-ch=\"feret\">Ферет</span>"],["dir","указывая на труп <span class=\"ch\" data-ch=\"alkesta\">Алькесты</span>"],["v","Вот в этой был и стыд, да без рассудка.",0,728,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Уйди, молю. Дай схоронить ее.",0,729,0,0],["sp","<span class=\"ch\" data-ch=\"feret\">Ферет</span>"],["v","Не задержусь. А ты, женоубийца,",0,730,0,1],["v","Алькестиной поплатишься семье:",0,730,0,0],["v","Среди мужей Акаста хоть не числи,",0,731,0,0],["v","Коль за сестру тебе не отомстит.",0,732,0,0],["sd","(Уходит со свитой и дарами.)"],["scene","Явление двенадцатое","s16",4,16],["v","Без <span class=\"ch\" data-ch=\"feret\">Ферета</span> и свиты.",0,733,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["dir","вослед уходящему"],["v","Проклятье вам — тебе и сень с тобою",0,734,0,0],["v","Делящей; пусть при сыне вы живом",0,735,0,0],["v","Бездетными на старости слывете.",0,735,0,0],["v","А мой чертог — отныне вам закрыт.",0,736,0,0],["v","И если б чрез глашатаев пришлось мне",0,737,0,0],["v","Порвать навек с отцовским очагом,",0,738,0,0],["v","Не откажусь. Но горе нас торопит.",0,739,0,0],["v","Почившую святить огнем пора.",0,740,0,1],["v","Тело поднимают. Плач.",0,740,0,0],["sp","Корифей"],["v","Преступная дерзость. Увы!",0,741,0,0],["v","А ты, между жен благородных",0,742,0,0],["v","О лучшая, ныне прости нам,",0,743,0,0],["v","Да благ тебе будет Гермес",0,743,0,0],["v","И мрачный Аид, а если",0,744,0,0],["v","Там добрым бывает награда,",0,745,0,0],["v","Ты с дивной Аида воссядешь,",0,746,0,0],["v","Дары разделяя, невестой.",0,746,0,0],["sd","Шествие медленно удаляется. Хор сопровождает гроб, покидая орхестру. <span class=\"ch\" data-ch=\"admet\">Адмет</span> идет за гробом понурившись."],["scene","Явление тринадцатое","s17",4,17],["sd","Раб (из дому, из боковой двери)"],["v","Гостей видал я многих. Приходили<a class=\"nr\" href=\"#n-k29\" data-n=\"k29\" aria-label=\"Примечание 29\">29</a>",0,747,0,0],["v","Из разных стран к <span class=\"ch\" data-ch=\"admet\">Адмету</span> и за стол",0,748,0,0],["v","За пировой садились. Но такого",0,749,0,0],["v","Мне не пришлось еще у очага",0,750,0,1],["v","Сажать… Царя он в трауре находит",0,750,0,0],["v","И все-таки идет в его чертог.",0,751,0,0],["v","Мы подали что есть: другой бы, скромный,",0,752,0,0],["v","Уважив горе, голод утолил",0,753,0,0],["v","Поставленным на стол… А этот просто",0,754,0,0],["v","Нас загонял… Ну, кончился обед —",0,755,0,0],["v","Берет он кубок емкий: чистым даром",0,755,0,0],["v","Земли его он наполняет черной",0,756,0,0],["v","И пьет, пока огонь вина по жилам",0,757,0,0],["v","Не побежал. Он миртовой потом",0,758,0,0],["v","Там голову себе венчает веткой,",0,759,0,0],["v","Сбираясь петь. То был какой-то лай…",0,760,0,1],["v","И странно так мешались звуки: горя",0,760,0,0],["v","Адметова чуждаясь, песню гость",0,761,0,0],["v","Выкрикивал, мы ж, челядинцы, выли",0,762,0,0],["v","По госпоже, не смея пришлецу",0,763,0,0],["v","Глаз показать заплаканных — то воля",0,764,0,0],["v","Адметова была. И вот теперь",0,765,0,0],["v","Какого-то проныру, вора, плута,",0,766,0,0],["v","Грабителя, быть может, угощать",0,767,0,0],["v","Я должен, не почтив царицы мертвой",0,768,0,0],["v","Ни плачем, ни руки благословеньем.",0,769,0,0],["sd","(Плачет.)"],["v","Ведь мать была покойная рабам",0,770,0,1],["v","И сколько раз от тягостного гнева",0,770,0,0],["v","Спасала нас Адметова. Ну что ж?",0,771,0,0],["v","Иль я не прав, что этот гость не в пору?",0,772,0,0],["scene","Явление четырнадцатое","s18",4,18],["sd","Слуга и <span class=\"ch\" data-ch=\"gerakl\">Геракл</span>, увенчанный миртом, с горящими глазами, без оружия."],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Ты! Что глядишь угрюмо, что тебя",0,773,0,0],["v","Заботит, раб? Когда гостям ты служишь,",0,774,0,0],["v","Печальным их лицом ты не смущай,",0,775,0,0],["v","Приветлив будь. Перед тобой товарищ",0,776,0,0],["v","Хозяина, а ты надул лицо,",0,777,0,0],["v","Нахмурился — беда чужая мучит…",0,778,0,0],["v","Иди сюда, учись, умнее будешь:",0,779,0,0],["v","Ты знаешь ли, в чем наша жизнь?",0,780,0,1],["v","Поди,",1,780,0,0],["v","Не знаешь, раб? Да и никто не знает,",0,781,0,0],["v","Жив будет ли наутро. Нам судьба",0,782,0,0],["v","Путей не открывает: ни наукой,",0,783,0,0],["v","Ни хитростью ее не купишь тайн.",0,784,0,0],["v","Сообрази ж и веселись. За кубком",0,785,0,0],["v","Хоть день, да твой, а завтра, чье-то завтра?",0,790,0,1],["v","Ты из богов почти особо, друг,",0,791,0,0],["v","Сладчайшую для смертного, Киприду.",0,792,0,0],["v","И — в сторону все прочее! Моим",0,793,0,0],["v","Словам, коль прав тебе кажусь я, следуй.",0,794,0,0],["v","А, кажется, я прав…",0,795,0,0],["v","Пойдем со мной,",1,795,0,0],["sd","(хлопает его по плечу)"],["v","Венками мы украсимся, и живо",0,796,0,0],["v","От мрачных дум веселый плеск вина",0,797,0,0],["v","О кубка борт тебя, поверь, отчалит.",0,798,0,0],["v","Спесивому ж да хмурому, коль суд",0,800,0,1],["v","Ты примешь мой, не жизнь, а только мука.",0,801,0,0],["sp","Слуга"],["v","Все это нам известно. Но теперь",0,802,0,0],["v","Не до вина и не до смеху в доме.",0,803,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Но умерла чужая ведь. Чего ж",0,804,0,0],["v","Вам горевать, когда свои-то целы?",0,805,0,0],["sp","Слуга"],["v","Кто цел? Беду-то нашу ты забыл?",0,806,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Скажи: не знал, коли <span class=\"ch\" data-ch=\"admet\">Адмету</span> верить…",0,807,0,0],["sp","Слуга"],["v","К гостям-то он не в меру добр, <span class=\"ch\" data-ch=\"admet\">Адмет</span>.",0,808,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Из-за чужих же мертвых нам не плакать!",0,810,0,1],["sp","Слуга"],["v","Чужих? Уж то-то очень не чужих.",0,811,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Он от меня не скрыл беды, надеюсь?",0,812,0,0],["sp","Слуга"],["v","Иди, пируй. Господ мы делим горе.",0,813,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Иль речь идет не о чужой беде?",0,814,0,0],["sp","Слуга"],["v","Когда бы так, ужли б я стал сердиться?",0,815,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Иль надо мной хозяин подшутил?",0,816,0,0],["sp","Слуга"],["v","В печальный дом ты б не вошел, пожалуй {*}.",0,817,0,1],["v","{* Стихи 818-819:",0,817,0,0],["sp","Слуга"],["v","Не вовремя пришел ты к нам. Над домом<a class=\"nr\" href=\"#n-k30\" data-n=\"k30\" aria-label=\"Примечание 30\">30</a>",0,818,0,0],["v","Нависло горе. Ты ведь видишь? В черном",0,818,0,0],["v","Мы все, остригли кудри…}",0,819,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Старик отец иль из детей кто умер?",0,820,0,1],["sp","Слуга"],["v","Адметова жена скончалась, гость.",0,820,0,0],["sd","Минута молчания."],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Что говоришь? Я пировал у мертвой?",0,821,0,0],["sp","Слуга"],["v","Дверь от тебя стыдился он закрыть.",0,822,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Проклятие! Такой жены лишиться…",0,823,0,0],["sp","Слуга"],["v","Всех нас она сгубила в доме, всех.",0,824,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","В глазах его, конечно, были слезы:",0,825,0,0],["v","Печаль лица и стрижки он не скрыл…",0,826,0,0],["v","Но объяснил, что в землю опускают",0,827,0,0],["v","Чужого человека. И, прогнав",0,828,0,0],["v","Сомнения, в распахнутые двери",0,829,0,0],["v","Вошедши, пил под кровом друга я,",0,830,0,1],["v","Пока он здесь стонал. И до сих пор я",0,830,0,0],["v","В венке… И ты виновен в этом, раб!",0,831,0,0],["sd","(Срывает и ломает миртовую ветвь.)"],["v","Зачем беду таил? Но где ж царицу",0,832,0,0],["v","Хоронят? Где найду ее, скажи?",0,833,0,0],["sp","Слуга"],["v","Дорога здесь прямая на Лариссу:",0,834,0,0],["v","Как выйдешь из поселка, гроб ее",0,835,0,0],["v","Ты отличишь по вытесанным камням.",0,835,0,0],["sd","(Уходит в дом.)"],["scene","Явление пятнадцатое","s19",4,19],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["dir","один"],["v","Ты, сердце, что дерзало уж не раз,",0,836,0,0],["v","Ты, мощная десница: вам сегодня",0,837,0,0],["v","Придется показать, какого сына",0,838,0,0],["v","Тиринфская Алкмена родила",0,839,0,0],["v","Царю богов. Жену, что так недавно",0,840,0,1],["v","В холодный гроб отсюда унесли,",0,840,0,0],["v","Я в этот дом верну на радость другу.",0,841,0,0],["v","Я в ризе черной демона, царя",0,842,0,0],["v","Над мертвыми, выслеживать отправлюсь,",0,843,0,0],["v","Его настичь надеюсь у могил,",0,844,0,0],["v","До близкой жертвы жадного. Засаду",0,845,0,0],["v","Покинув, пряну я и обовью",0,846,0,0],["v","Руками Смерть. И нет руки на свете,",0,847,0,0],["v","Чтоб вырвала могучую, пока",0,848,0,0],["v","Мне не вернет жены. А коль охота",0,849,0,0],["v","На демона не сладится и он",0,850,0,1],["v","Кровавого вкусить не выйдет брашна,",0,850,0,0],["v","Я опущусь в подземное жилье,",0,851,0,0],["v","В тот мрачный дом царя глубин и Коры…",0,852,0,0],["v","Я умолю, уговорю богов;",0,853,0,0],["v","И мне дадут <span class=\"ch\" data-ch=\"alkesta\">Алькесту</span>, чтоб в объятья",0,854,0,0],["v","Адметовы я мог ее вернуть.",0,855,0,0],["v","Тяжелою десницей пораженный",0,855,0,0],["v","Судьбы, меня он пира не лишил,",0,856,0,0],["v","Он чтил во мне так благородно гостя.",0,857,0,0],["v","В Фессалии, во всей Элладе кто",0,858,0,0],["v","В радушии сравнится с ним? Но мужа",0,859,0,0],["v","Не слабого, клянусь, и он ласкал.",0,860,0,1],["sd","(Уходит.)"],["scene","Явление шестнадцатое","s20",4,20],["scene","Коммос","s21",4,21],["sd","(с новым вступлением хора)"],["v","<span class=\"ch\" data-ch=\"admet\">Адмет</span> и хор возвращаются в орхестру.",0,860,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Увы! Увы! О, ужас возвращенья!",0,861,0,0],["v","О, вид постылый! В доме опустелом",0,862,0,0],["v","Так страшно. Горе, горе надо мной.",0,862,0,0],["v","Куда же пойду я? Где стану?",0,863,0,0],["v","Что словом оплачу? Что молча?",0,864,0,0],["v","На злую рожденный судьбину,",0,864,0,0],["v","О, лучше б я умер!",0,865,0,0],["v","Жребий почивших завиден,",0,866,0,0],["v","Темный покой их так сладок.",0,866,0,0],["v","Солнца мне тяжко сиянье,",0,867,0,0],["v","Тошно мне двигать ногами.",0,868,0,0],["v","Смертью в борьбе непосильной",0,868,0,0],["v","Вырван из рук заложник;",0,869,0,0],["v","Лучший заложник жизни",0,870,0,1],["v","Там, в плену у Аида.",0,870,0,0],["v","Хор",0,871,4,0],["str","Строфа I"],["v","Пройди ж и затаися",0,871,0,0],["v","В покое отдаленном.",0,872,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Ой, лихо мне!",0,873,0,0],["sp","Хор"],["v","Да, жребий твой достоин слез.",0,873,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","О, тяжко мне!",0,874,0,0],["sp","Хор"],["v","Твой путь через страданье,",0,875,0,0],["v","Я знаю это.",0,875,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Да, увы!",1,875,0,0],["sp","Хор"],["v","Но мертвой не поможешь ты.",0,876,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Увы! Увы!",0,876,0,0],["sp","Хор"],["v","Не видеть никогда",1,876,0,0],["v","Черты лица любимого так горько…",0,877,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Сердце мое ты ранишь словами:",0,878,0,0],["v","Мужу верной жены",0,878,0,0],["v","Есть ли потеря ужасней?",0,879,0,0],["v","Лучше бы с нею чертога",0,880,0,1],["v","Мне не делить было,",0,880,0,0],["v","Жребий безбрачных, жребий",0,881,0,0],["v","Мне бездетных завиден.",0,882,0,0],["v","Из-за души единой",0,883,0,0],["v","Легче им скорби бремя.",0,883,0,0],["v","Невыносимо видеть",0,884,0,0],["v","Этих детей болящих,",0,885,0,0],["v","Видеть на брачном ложе",0,886,0,0],["v","Это насилие смерти.",0,886,0,0],["v","Жизнь скоротать легче",0,887,0,0],["v","Людям, коль брака чужды.",0,888,0,0],["sp","Хор"],["sd","Антистрофа I Судьбой необоримой Настигнут ты, судьбою!"],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Ой, тяжко мне!",0,889,0,0],["sp","Хор"],["v","И бедствиям предела нет.",0,890,0,1],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","О, горе мне!",0,890,0,0],["sp","Хор"],["v","Но силы для терпенья",0,891,0,0],["v","Нужны тебе.",0,892,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Увы! Увы!",1,892,0,0],["sp","Хор"],["v","Мужайся! Ты ль один терял…",0,892,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Увы! Увы!",0,893,0,0],["sp","Хор"],["v","Жену? Людей несчастье никогда",0,894,0,0],["v","Не пощадит, но, настигая, душит.",0,894,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","О, долгая скорбь о друге,",0,895,0,0],["v","В землю от нас ушедшем!..",0,896,0,0],["v","О, для чего ж ты мне не дал",0,896,0,0],["v","С ней остаться в могиле?",0,897,0,0],["v","Мертвому, хладное ложе",0,898,0,0],["v","С лучшей из жен разделить мне?..",0,898,0,0],["v","Вместо одной Аиду",0,899,0,0],["v","Две бы досталось тени,",0,900,0,1],["v","В лодке Харона дружных,",0,901,0,0],["v","В доме его слитых…",0,902,0,0],["sp","Хор"],["str","Строфа II"],["v","Истинно слез достойный",0,903,0,0],["v","Случай у нас был: умер",0,904,0,0],["v","Юноша, был у отца он",0,905,0,0],["v","Только один. Но стойко",0,906,0,0],["v","Нес отец свое горе;",0,907,0,0],["v","А сединою волос",0,908,0,0],["v","Был у него подернут:",0,909,0,0],["v","Жизнь уже шла к закату.<a class=\"nr\" href=\"#n-k31\" data-n=\"k31\" aria-label=\"Примечание 31\">31</a>",0,910,0,1],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","В дом этот страшно войти мне.",0,911,0,0],["v","Как буду жить в нем? Иная",0,912,0,0],["v","Доля мне выпала. Помню,",0,913,0,0],["v","Факелы с высей пелийских",0,914,0,0],["v","Путь нам сюда озаряли,",0,915,0,0],["v","Брачные песни помню…",0,916,0,0],["v","За руку вел жену я,",0,917,0,0],["v","Светлый шел хор следом,",0,918,0,0],["v","Славил меня с <span class=\"ch\" data-ch=\"alkesta\">Алькестой</span>.",0,919,0,0],["v","Знатны мы. Сколько было",0,920,0,1],["v","Блеска в вельможной свите!",0,920,0,0],["v","Плач погребальный лики",0,921,0,0],["v","Брака сменяет… Черной",0,922,0,0],["v","Ризою блеск покрылся.",0,923,0,0],["v","И на пустое ложе",0,924,0,0],["v","В дом одиноко влачусь я.",0,925,0,0],["sp","Хор"],["str","Антистрофа II"],["v","Мимо тебя покуда",0,925,0,0],["v","Горе всегда проходило, —",0,926,0,0],["v","Слыл ты, Адмет, счастливцем,",0,927,0,0],["v","Что ж? Ты сберег и ныне",0,928,0,0],["v","Жизни дыханье. Нежно",0,929,0,0],["v","Мертвой красу любил ты…",0,930,0,1],["v","Но и других демон",0,931,0,0],["v","Милой жены лишает!",0,932,0,0],["act","Действие четвертое","a5","IV"],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Друзья мои! Почившая счастливей,",0,933,0,0],["v","Чем муж ее. Что солнце? Что Аид?",0,934,0,0],["v","Уж никогда и никакое горе",0,935,0,0],["v","<span class=\"ch\" data-ch=\"alkesta\">Алькесты</span> не коснется: от забот",0,936,0,0],["v","Свободная, она приемлет славу",0,937,0,0],["v","Великую. А что дала <span class=\"ch\" data-ch=\"admet\">Адмету</span>",0,938,0,0],["v","Такой ценой им купленная жизнь?",0,940,0,1],["v","Вот я сейчас ступлю за эти двери…",0,941,0,0],["v","И кто же мне навстречу выйдет? Кто",0,942,0,0],["v","Мне на привет ответит? А куда же,",0,943,0,0],["v","Коль не домой, идти? Войду, и дом",0,944,0,0],["v","Меня сейчас назад погонит; кресло,",0,945,0,0],["v","Кровать ее увижу, неметеный",0,946,0,0],["v","Порог, детей, которые, ко мне",0,947,0,0],["v","В колени прячась, мать зовут и плачут..",0,948,0,0],["v","Я стоны слуг услышу, что такой",0,949,0,0],["v","Им не видать царицы. Трудно дома,",0,950,0,1],["v","Не веселей и в людях. Или брак,",0,950,0,0],["v","Иль общество веселое, где жены",0,951,0,0],["v","Напомнят мне <span class=\"ch\" data-ch=\"alkesta\">Алькесту</span> — и домой",0,952,0,0],["v","Потянет, в этот дом?.. А то приятель",0,953,0,0],["v","Какой, меня увидев, скажет: \"Вот",0,954,0,0],["v","Позором жизнь себе купивший! смерти",0,955,0,0],["v","Он избежал, отдав свою жену",0,956,0,0],["v","Аиду. Что ж родителей корит он,",0,957,0,0],["v","Коль струсил сам?\" О, новая молва,",0,958,0,0],["v","Привесок к злу <span class=\"ch\" data-ch=\"admet\">Адмета</span>! Для чего ж,",0,959,0,0],["v","Скажите, жить еще, когда ни счастья,",0,960,0,1],["v","Ни славы мне уж доброй не вернуть?",0,960,0,0],["scene","Четвертый музыкальный антракт","s22",5,22],["sp","Хор"],["str","Строфа I"],["v","Музам послушный,",0,961,1,0],["v","К звездным вздымался я высям,",0,962,0,0],["v","Многих наук причастен,",0,963,0,0],["v","Но ужасней Судьбы я",0,964,0,0],["v","Силы не знаю, — средства",0,965,0,0],["v","Нет от нее на досках,",0,966,0,0],["v","Что покрыла для смертных",0,967,0,0],["v","Вещая речь Орфея.<a class=\"nr\" href=\"#n-k32\" data-n=\"k32\" aria-label=\"Примечание 32\">32</a>",0,968,0,0],["v","И от нее лекарства,",0,969,0,0],["v","Фебу послушны, не крошат",0,970,0,1],["v","Асклепиады прилежно.<a class=\"nr\" href=\"#n-k33\" data-n=\"k33\" aria-label=\"Примечание 33\">33</a>",0,971,0,0],["str","Антистрофа I"],["v","Ни алтарями,",0,972,0,0],["v","Ни в изваянье не чтима,",0,973,0,0],["v","Жертвы она не просит.",0,974,0,0],["v","Мне ж, царица, молю я,",0,975,0,0],["v","Будь ты такой, как прежде.",0,976,0,0],["v","То, что угодно Зевсу,",0,977,0,0],["v","Через тебя ведь творится.",0,978,0,0],["v","Ломишь железо даже —",0,979,0,0],["v","Славу, Судьба, халибов.<a class=\"nr\" href=\"#n-k34\" data-n=\"k34\" aria-label=\"Примечание 34\">34</a>",0,980,0,1],["v","И сожаленье чуждо",0,981,0,0],["v","Воле твоей холодной.",0,982,0,0],["str","Строфа II"],["v","И тебя, о Адмет, захватила Судьба",0,983,0,0],["v","В необорные руки свои.",0,984,0,0],["v","Но дерзай — ведь плачем к солнцу",0,985,0,0],["v","Ты усопшей не воротишь…",0,986,0,0],["v","И богов сыны вкушают",0,987,0,0],["v","Мрак могильный. Нам <span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>",0,988,0,0],["v","Здесь была всех жен милее.",0,990,0,1],["v","Мы ее и в царстве мертвых",0,991,0,0],["v","Чтим любовно. Благородней",0,992,0,0],["v","Жен не знало ложе брака.",0,993,0,0],["str","Антистрофа II"],["v","А могила ее не на смертную стать,",0,994,0,0],["v","Как божественный будет алтарь…",0,995,0,0],["v","Точно храм скитальцу будет,",0,996,0,0],["v","Для нее с пути склоняясь,",0,997,0,0],["v","Так иной промолвит путник:",0,1000,0,1],["v","\"Умерла она за мужа,",0,1000,0,0],["v","А теперь среди блаженных",0,1001,0,0],["v","И сама богиней стала,",0,1002,0,0],["v","Дай нам счастья, Алькестида!\"",0,1003,0,0],["v","Вот, Адмет, царицы слава.",0,1004,0,0],["sp","Корифей"],["v","Но посмотри: как будто сын Алкмены",0,1005,0,0],["v","Сюда идет… к тебе, конечно, царь!",0,1006,0,0],["act","Исход","a6",""],["scene","Явление семнадцатое","s23",6,23],["sd","Слева приходит <span class=\"ch\" data-ch=\"gerakl\">Геракл</span>. За ним нарядная и статная женщина, покрытая длинным покрывалом. <span class=\"ch\" data-ch=\"gerakl\">Геракл</span> и <span class=\"ch\" data-ch=\"admet\">Адмет</span>."],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Я не люблю, Адмет, гостя у друга,",0,1007,0,0],["v","Гнев на него в молчании копить.",0,1008,0,0],["v","Скажи мне, царь, иль я достоин не был",0,1009,0,0],["v","С тобой делить, как друг, твою печаль?",0,1010,0,1],["v","Ты от меня зачем-то скрыл, что в доме",0,1011,0,0],["v","Лежит <span class=\"ch\" data-ch=\"alkesta\">Алькеста</span> мертвая, сказав,",0,1012,0,0],["v","Что умерла чужая, и за пир",0,1013,0,0],["v","Заставил сесть, свершая возлиянье,",0,1014,0,0],["v","Увенчанным средь траурных палат…",0,1015,0,0],["v","Негодовать я должен бы, открывши",0,1016,0,0],["v","Обман, но зла к беде твоей, Адмет,",0,1017,0,0],["v","Не приложу. А для чего вернулся,",0,1018,0,0],["v","Узнайте все.",0,1020,0,1],["sd","(Указывая на свою спутницу.)"],["v","Вот женщина — ее",0,1020,4,0],["v","Не откажись сберечь, пока обратно",0,1021,0,0],["v","Не буду я из Фракии, царя",0,1022,0,0],["v","Бистонского убийца и властитель",0,1023,0,0],["v","Его лихих коней. Избави бог,",0,1023,0,0],["v","Не ворочусь — а лучше бы вернуться, —",0,1024,0,0],["v","Рабой тебе пусть остается, царь.",0,1025,0,0],["v","Больших трудов мне стоила. На играх,",0,1026,0,0],["v","Предложенных атлетам, получил",0,1026,0,0],["v","Я этот славный приз.",0,1027,0,0],["v","Сначала были",1,1027,0,0],["v","Там состязанья легкие, коней",0,1028,0,0],["v","Давали победителям, труднее",0,1029,0,0],["v","Была борьба и бой кулачный — тут",0,1030,0,1],["v","Осилившим стада быков давали.",0,1030,0,0],["v","Последний приз была жена. Не взять,",0,1031,0,0],["v","Раз случай есть, мне стыдно показалось",0,1032,0,0],["v","Такой награды дивной. Сбереги ж",0,1033,0,0],["v","Ее, Адмет, когда-нибудь потом",0,1034,0,0],["v","Сам, может быть, ты мне спасибо скажешь.",0,1035,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["dir","отстраняя рукой предложение"],["v","И в помыслах <span class=\"ch\" data-ch=\"gerakl\">Геракла</span> оскорбить",0,1036,1,0],["v","Я не держал… Такой ли враг бывает?",0,1037,1,0],["v","Нет, если скрыл я смерть жены, так только",0,1038,1,0],["v","Чтоб нового страданья не принять,",0,1039,1,0],["v","Чужой очаг указывая другу.",0,1040,1,1],["v","Я не искал товарища беду",0,1040,1,0],["v","Домашнюю оплакивать.",0,1041,1,0],["v","Но эту",1,1041,0,0],["sd","(указывая с некоторым страхом на женщину)"],["v","Другим отдай, пожалуйста, герой,",0,1042,1,0],["v","Которым жен сегодня хоронить",0,1043,1,0],["v","Не приходилось, между фессалийцев.",0,1044,1,0],["v","Не береди мне раны. На нее",0,1045,1,0],["v","Без слез глядеть не мог бы я… В чертоге",0,1046,1,0],["v","Несчастий мне довольно и своих…",0,1047,1,0],["v","Судьбой и так подавлен я…",0,1048,1,0],["v","И где ж бы",1,1048,0,0],["v","Я поместил ее? Так молода…",0,1049,1,0],["sd","(Разглядывая рабу.)"],["v","О, молода, конечно… Что за пеплос!",0,1050,1,1],["v","Какой убор! Среди мужчин ее",0,1050,1,0],["v","Не поместишь… Да, между них вращаясь,",0,1051,1,0],["v","И чистой не остаться б ей. Ведь юных",0,1052,1,0],["v","Удержишь разве! Здесь я о тебе,",0,1053,1,0],["v","Конечно, думаю… Иль ей открыть",0,1054,1,0],["v","Покой жены? Но разве ж я дерзну",0,1055,1,0],["v","Алькестино отдать рабыне ложе?",0,1056,1,0],["v","Посыплются упреки на меня,",0,1057,1,0],["v","Пойдет молва, что, верно, изменяю",0,1058,1,0],["v","Я той, которая меня спасла…",0,1059,1,0],["v","Да и самой царицы память надо",0,1060,1,1],["v","Мне чистою среди людей хранить.",0,1060,1,0],["v","Ее ль забыть? О нет! А ты, рабыня,",0,1061,1,0],["v","Не знаю, кто ты? Но <span class=\"ch\" data-ch=\"alkesta\">Алькесту</span> мне",0,1062,1,0],["v","Напоминаешь. Тот же рост и стан.",0,1063,1,0],["v","О, горе мне!",0,1064,1,0],["sd","(К <span class=\"ch\" data-ch=\"gerakl\">Гераклу</span>.)"],["v","Ради богов, скорее",0,1065,4,0],["v","С глаз уведи ее моих: того,",0,1065,1,0],["v","Кто уж убит, не убивай вторично.",0,1066,1,0],["v","Я будто тень <span class=\"ch\" data-ch=\"alkesta\">Алькесты</span> увидал:",0,1067,1,0],["v","Мутится ум, и слез бегут потоки,",0,1068,1,0],["v","И рана вновь открылась. Пожалей…",0,1069,1,0],["sd","(Плачет.)"],["sp","Корифей"],["v","Благословлять судьбу не предлагаю,",0,1070,0,1],["v","Но если бог что дал тебе — носи…",0,1071,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","О, если бы такую мощь имел я,",0,1072,0,0],["v","Чтоб из глубин земли на божий свет",0,1073,0,0],["v","Жену тебе, Адмет, вернуть на радость!",0,1074,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Ты бы желал, я знаю. Только где ж?",0,1075,0,0],["v","Здесь, на Земле, людей не воскрешают…",0,1076,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Смиряй себя и свой удел носи…",0,1077,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Терпение, герой, трудней совета.",0,1078,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Из слез нам, царь, не выковать судьбы.",0,1079,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Конечно нет. Но их любовь рождает.",0,1080,0,1],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Да, мертвого нельзя любить без слез…",0,1080,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Нет слов, Геракл, обнять мою утрату.",0,1081,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Ты потерял примерную жену…",0,1082,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","А с ней навек и радости супруга.",0,1083,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Печаль твою смягчат года, <span class=\"ch\" data-ch=\"admet\">Адмет</span>:",0,1084,0,0],["v","Теперь она, конечно, в полной силе.",0,1085,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Зачем года?.. Скажи короче — смерть…",0,1086,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Тоски жена убавит молодая…",0,1087,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Что говоришь? Молчи. Иль я женюсь?",0,1088,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Не женишься? Вдоветь покинешь ложе?..",0,1089,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Избранница моя не родилась…",0,1090,0,1],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Что ж? Мертвую ты ублажаешь этим?",0,1091,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Где б ни была, ее я должен чтить.",0,1092,0,0],["sd","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span> Хвалю в тебе супруга, не безумца…"],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Безумец, пусть. Но только не жених.",0,1093,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Ты — верный друг покойной, очень верный.",0,1094,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","И смерть меня накажет, если я",0,1095,0,0],["v","Ей изменю, хотя она в могиле.",0,1096,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Но в дом прими ее: будь добрый друг.",0,1097,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Нет, нет, отцом тебя молю я Зевсом.",0,1098,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Ты пожалеешь, царь, что отказал.",0,1099,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Приняв ее, я сердцем истерзаюсь…",0,1100,0,1],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Послушайся. Сам будешь рад потом.",0,1101,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Увы! Зачем ты брал награду эту?",0,1102,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Чтоб верный друг со мной ее делил.",0,1103,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Хвалю тебя. Но удали добычу!",0,1104,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Коль надобно. Но надо ли, скажи.",0,1105,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Не гневайся. Я уверяю — надо.",0,1106,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Упорствуя, я тоже ведь не слеп.",0,1107,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Я уступлю тебе, но без желанья.",0,1108,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Потом меня похвалишь: покорись.",0,1109,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["dir","слугам"],["v","Эй! Проводить в чертоги эту гостью!",0,1110,0,1],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Я бы рабам ее не поручал.",0,1111,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Тогда введи ее хоть сам, пожалуй.",0,1112,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["dir","выразительно"],["v","<em>Тебе</em> хочу с рук на руки отдать.",0,1113,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["dir","нетерпеливо"],["v","Я не коснусь ее: сама пусть входит.",0,1114,0,0],["sd","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span> Деснице я <em>твоей</em> ее вверял."],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Насилье, царь. Тут воли нет <span class=\"ch\" data-ch=\"admet\">Адмета</span>.",0,1115,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Коснись до ней, ты только прикоснись.",0,1116,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["dir","протягивая руку"],["v","Ну, вот моя рука. Но, право, будто",0,1117,0,0],["v","Мне голову рубить Горгоне надо.",0,1118,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Взял за руку?<a class=\"nr\" href=\"#n-k35\" data-n=\"k35\" aria-label=\"Примечание 35\">35</a>",0,1119,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["sd","Держу."],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["dir","сдергивая покрывало"],["v","И береги,",1,1119,0,0],["v","А Зевсова отныне числи сына",0,1120,0,1],["v","Ты благородным гостем. Погляди ж.",0,1121,0,0],["v","Что? На кого похожа? Вытри слезы.",0,1122,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["dir","после минутной паузы"],["v","О боги… Нет… Иль это чудо? Нет…",0,1123,0,0],["v","Передо мной <span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>. Не глумится ль",0,1124,0,0],["v","Над горьким бог какой-нибудь, скажи?",0,1125,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Нет, точно здесь жена твоя, <span class=\"ch\" data-ch=\"alkesta\">Алькеста</span>.",0,1126,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Не призрак ли ее, смотри, Геракл!",0,1127,0,0],["sd","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span> Твой гость пока, а не Гермес с тобою."],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Не сам ли я <span class=\"ch\" data-ch=\"alkesta\">Алькесту</span> хоронил?<a class=\"nr\" href=\"#n-k36\" data-n=\"k36\" aria-label=\"Примечание 36\">36</a>",0,1128,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Уверься, друг… Хоть, точно, это странно.",0,1130,0,1],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Могу ль до ней коснуться и привет",0,1130,0,0],["v","К ней обратить?",0,1131,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Пожалуйста, Адмет…",1,1131,0,0],["v","Чего желал, ты всем теперь владеешь.",0,1132,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["dir","обнимая неподвижную, бледную и безмолвную <span class=\"ch\" data-ch=\"alkesta\">Алькесту</span>"],["v","О милые черты! О нежный стан…",0,1133,0,0],["v","Мечтал ли я, что вас опять увижу?",0,1134,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Она — твоя. Богов, однако ж, бойся",0,1135,0,0],["v","Завистливых…",0,1135,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","О благородный сын",1,1135,0,0],["v","Великого Кронида, будь же счастлив.",0,1136,0,0],["v","Да сохранит тебя отец за то,",0,1137,0,0],["v","Что ты один и нас и дом восставил.",0,1138,0,0],["v","Но как же ты ее добился воли?",0,1139,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Затеял бой я с демонским царем.",0,1140,0,1],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Ты с демоном сражался смерти, точно?",0,1140,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Над самою могилой оцепил",0,1141,0,0],["v","Его руками я, засаду кинув.",0,1142,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Но отчего ж она молчит, скажи?",0,1143,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Богам она посвящена подземным,",0,1144,0,0],["v","И, чтоб ее ты речи услыхал,",0,1145,0,0],["v","Очиститься ей надо, и три раза",0,1145,0,0],["v","Над ней должно, Адмет, смениться солнце.",0,1146,0,0],["v","Но в дом веди ее.",0,1147,0,0],["v","А сам всегда",1,1147,0,0],["v","Будь справедлив и гостя чти. Простимся.",0,1148,0,0],["v","Мне предстоит работа: для царя",0,1149,0,0],["v","Свершу ее, рожденного Сфенелом.<a class=\"nr\" href=\"#n-k37\" data-n=\"k37\" aria-label=\"Примечание 37\">37</a>",0,1150,0,1],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Останься здесь: будь гостем дорогим.",0,1150,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Нет, до другого раза. Дело ждет.",0,1151,0,0],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Ну, добрый путь тебе, возврат счастливый!",0,1152,0,0],["sd","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span> уходит."],["scene","Явление восемнадцатое,","s24",6,24],["sd","и последнее"],["sd","Без <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>."],["sp","<span class=\"ch\" data-ch=\"admet\">Адмет</span>"],["v","Вы, граждане всех четырех концов",0,1153,0,0],["v","Фессалии, почтите хороводом<a class=\"nr\" href=\"#n-k38\" data-n=\"k38\" aria-label=\"Примечание 38\">38</a>",0,1154,0,0],["v","Счастливый день, и жир на алтарях",0,1155,0,0],["v","Пускай, дымясь, богам отраден будет!",0,1156,0,0],["v","Я зависти небесной не боюсь",0,1157,0,0],["v","И солнцу говорю: «Гляди — я счастлив».",0,1158,0,0],["sd","(Уходит в дом с <span class=\"ch\" data-ch=\"alkesta\">Алькестой</span> среди радостных восклицаний.)"],["v","Последние лучи солнца.",0,1159,0,0],["sp","Хор"],["dir","удаляется под мерные звуки анапестов"],["v","Воли небесной различны явленья:",0,1160,0,1],["v","Смертный не может ее угадать.",0,1161,0,0],["v","Много проходит бесследно надежд,",0,1162,0,0],["v","Многое боги нежданно дают,",0,1163,0,0],["v","Драме ж на этом и славу поют…",0,1164,0,0],["h1","Комментарий","comm"],["p","Согласно античным свидетельствам, Еврипид написал девяносто две драмы, часть которых была утеряна довольно рано. Однако александрийские филологи III в. до н. э. еще располагали не менее чем семьюдесятью пятью его подлинными произведениями, и выпущенное ими издание было широко известно в античном мире в течение последующих четырех-пяти веков. Во II в. н. э., вероятно, во времена римского императора Адриана (117 — 138), неизвестный составитель, руководствуясь сложившимися читательскими симпатиями и нуждами школы, отобрал из трагедий великих афинских драматургов по семь произведений Эсхила и Софокла и десять — Еврипида («Алькеста», «Медея», «Ипполит», «Андромаха», «Гекуба», «Троянки», «Финикиянки», «Орест», «Вакханки» и «Рес»). К этому изданию восходят четыре средневековые рукописи XII — XIII вв., в то время как две рукописи XIV в. содержат, кроме перечисленных выше, еще девять пьес Еврипида. Так как их названия начинаются со следующих в греческом алфавите друг за другом букв Е, Н, I, К (эпсилон, эта, йота, каппа), а в античных изданиях трагиков драмы следовали друг за другом как раз в алфавитном порядке названий, то не вызывает сомнений история возникновения подобного свода трагедий Еврипида: какому-то издателю случайно попали в руки два папирусных тома из полного собрания произведений Еврипида, которые он и присоединил к уже имевшему широкое хождение сборнику из десяти пьес. Кем и когда было составлено это более обширное издание, не известно; судя по находимым до сих пор папирусным отрывкам, Еврипида читали в греческих городах Египта вплоть до V-VI вв. н. э. Как показывают рукописи, обнаруженные совсем недавно в Хирбет-Мирде (район Мертвого моря), трагедии Еврипида попали на рубеже раннего Средневековья в иудейские поселения Палестины или даже к населявшим их позже арабам. Во всяком случае, до нового времени дошло девятнадцать произведений Еврипида, в том числе сравнительно большая группа трагедий последних лет его жизни (от «Электры» до «Ифигении в Авлиде») и единственная целиком сохранившаяся сатировская драма «Киклоп». Принадлежность Еврипиду дошедших произведений бесспорна, кроме трагедии «Рес», в подлинности которой возникли сомнения уже в древности. Недостатки в драматическом построении и ряд стилистических особенностей приводят большинство современных исследователей к мысли, что «Рес» написан в IV в. — может быть, не без влияния одноименной трагедии Еврипида, впоследствии утраченной. В настоящем издании она помещена в приложении ко II тому."],["p","Первые переводы Еврипида на русский язык стали появляться в начале XIX в.: еще А. Мерзляков перевел отрывки из «Алькестиды», «Гекубы» и «Ифигении в Тавриде». До сих пор сохраняют художественное значение переводы В. И. Водовозова («Ифигения в Авлиде», 1888), В. Г. Аппельрота («Гераклиды», 1890), Д. С. Мережковского («Медея», «Ипполит», 1895, 1902 и ряд переизданий), А. В. Артюшкова («Ион», «Киклоп», в его сб. «Котурн и маски», 1912), А. И. Пиотровского («Ипполит», в его сб. «Древнегреческая драма», 1937; несколько неизданных переводов А. И. Пиотровского хранятся в РГАЛИ). Но единственным поэтом, который осуществил перевод полного корпуса драм Еврипида, оставался Иннокентий Федорович Анненский (1855 — 1909), один из первых русских символистов. Он работал над ним около 15 лет, это стало подвигом его жизни. Для русского читателя XX в. Еврипид воспринимается только через призму перевода Анненского; настоящее издание — это литературный памятник сразу двух эпох, греческой классики и русского модернизма."],["p","Перевод Анненского высокохудожествен, но это не значит, что он идеален. В духе своего времени Анненский представлял себе Еврипида таким, каким ощущал себя сам: утонченным, одиноким, непонятым — так сказать, облагороженным и гармонизированным образом «проклятого» поэта-декадента. От лица такого Еврипида он и писал свои русские тексты еврипидовских драм. Современникам это было очевидно. Ф. Ф. Зелинский, его товарищ по филологии и сам переводчик Софокла, писал в статье «Памяти И. Ф. Анненского»: «То, что нам дал И. Ф., — это не просто русский Еврипид, а именно русский Еврипид И. Ф. Анненского, запечатленный всеми особенностями его индивидуальности. Мы можем сколько угодно отмечать его несогласие с подлинным Еврипидом; но если бы мы пожелали — и смогли — передать последнего по-своему, то все-таки вышел бы именно наш Еврипид, а не Еврипид просто. Специально И. Ф. очень дорожил индивидуальными особенностями своего перевода и сдавался только перед очевидностью»."],["p","Читатель нашего издания не должен забывать об этом ни на минуту. Причины «несогласия» перевода Анненского «с подлинным Еврипидом» были разные. Вопервых, те издания греческого текста, с которых делал сто лет назад свои переводы Анненский, уже не могут считаться достаточно удовлетворительными: многие места в наши дни читаются и понимаются по-иному. Во-вторых, стиль Еврипида — монументально четкий, сжатый, связный, логичный, как и у других аттических трагиков, — не всегда вязался с его представлением о Еврипиде, и он начинал украшать его собственными средствами — эмоциональными эпитетами, прерывистыми интонациями, красивыми словами, порой нарочито анахроничными (герольд, девиз, вуаль и проч.). В-третьих, Анненский лишь условно передавал стиховую форму подлинника: в монологах и диалогах он переводил греческий «ямбический триметр» русским (более коротким) 5-стопным ямбом, избегал передачи маршевых анапестов (важных в трагедии), очень свободно передавал непривычный русскому читателю ритм хоровых партий, не всегда соблюдал симметрию строф и антистроф, изредка вводил рифму, которой античность не знала. От этого его перевод получался гораздо многословнее подлинника: на десять строк Еврипида у Анненского обычно приходится 12-13 строк перевода, это видно по нумерации на полях в нашем издании, соответствующей подлиннику, а не переводу. В-четвертых, наконец, он целиком от себя вписывал в текст Еврипида сценические ремарки, декораторские и режиссерские, руководствуясь только вкусами и представлениями своего времени: они должны были изображать не античную сцену, а идеальную сцену, будто бы «предносившуюся воображению поэта» (по изысканному выражению Ф. Ф. Зелинского)."],["p","Чтобы сквозь эту толщу стилистических деформаций читатель мог представить себе то, что действительно видел и слышал афинский зритель Еврипида, напомним, как выглядел греческий театр. Он располагался под открытым небом, ряды зрительских мест шли полукругом (обычно по склону холма), вмещая 20 — 30 тысяч человек. Представление происходило внизу, на круглой площадке — орхестре («плясовое место») с алтарем посредине. В представлении участвовали хор и только три актера, так что каждому обычно приходилось играть несколько ролей (предположительное распределение ролей между тремя актерами Анненский размечает в списках действующих лиц цифрами I, II, III). Позади орхестры единственной декорацией служила стена палатки («скены») с тремя дверями, в которой переодевались актеры; к ней вело несколько ступеней. Обычно она была расписана как фасад дворца или храма. Если актер выходил из средней двери, это значило, что он — царь или вождь, если из боковой — то лицо низшего ранга. Если актер входил на орхестру слева, это значило, что он пришел из ближних мест, если справа — то с чужой стороны. (Анненский не забывает упоминать об этом в ремарках.) Актеры играли в больших масках и в условных пышных одеждах — для царя, для служителя, для женщины, для человека в трауре и т. п.; это позволяло различать их издали, но никакая мимика в масках, конечно, была невозможна. Содержание пьесы было зрителям заранее неизвестно, поэтому начиналась трагедия монологом или диалогом, сообщавшим зрителю предысторию разыгрываемой мифологической ситуации. Эта начальная сцена называлась «пролог»; затем на орхестру вступал хор из 15 человек с «корифеем» (предводителем) во главе; вступительная песнь хора называлась «парод». Корифей иногда подавал реплики актерам, остальные хоревты только пели и плясали. Действие представляло собой чередование монологических и диалогических сцен («эписодиев») с песнями хора («стасимами»); Анненский называет эписодии «действие первое» и т. д., а стасимы — «первый музыкальный антракт» и т. д. Песни хора состояли из попарных «строф» и «антистроф» на один и тот же мотив и с одинаковыми движениями; изредка строфам и антистрофам предшествовал «проод», а в середине песни пелся «месод». Иногда песни пелись и актерами, особенно в «коммосах», сценах оплакивания, — соло («монодии») или в диалоге с хором; Еврипид особенно славился такими жалобными ариями. Заключительная сцена — после последней песни хора — называлась «эксод» (у Анненского — «исход»). Представить борьбу, убийство, ослепление и проч. в таком театре было невозможно — о них рассказывал вестник. Чтобы показать внутренность дворца (например, после детоубийства Геракла), на орхестру выкатывался специальный помост; Анненский в таких случаях обычно пишет: «Раскрываются двери дворца…» Чтобы представить появление бога (обычно в развязке трагедии), над палаткой выдвигался специальный балкон («альтан», называет его Анненский по-испански). Такова была реальность афинской сцены, которую Анненский всячески старался заслонить от читателя своими лирическими ремарками."],["p","Анненский не успел опубликовать при жизни все свои 19 переводов Еврипида. Отдельным двуязычным изданием вышли «Вакханки» (1894); в «Журнале Министерства народного просвещения» были напечатаны «Рес» (1896, 9 — 10), «Геракл» (1897, 7 — 9), «Ифигения-жертва» (1898, 4 — 5), «Электра» (1899, 4 — 5), «Орест» (1900,1 — 3), «Алькеста» (1901, 3), «Ипполит» (1902, 3 — 5), «Медея» (1903, 5 — 7); в журнале «Мир Божий» — «Финикиянки» (1898, 4); в 1906 г. вышел «Театр Еврипида», т. 1 (из предполагавшихся трех), включавший «Алькесту», «Медею», «Ипполита», «Геракла» и впервые публикуемых «Иона» и «Киклопа». Каждый перевод сопровождался статьей с разбором пьесы, но без примечаний. После смерти Анненского право на издание «Театра Еврипида» купило издательство М. и С. Сабашниковых и в 1916, 1917, 1921 гг. успело выпустить три тома (из предполагавшихся шести), включавших «Алькесту», «Вакханок», «Геракла», «Ипполита», «Ифигению Авлидскую», «Иона», «Киклопа» и впервые публикуемых «Андромаху», «Гекубу», «Гераклидов», «Елену» и «Ифигению Таврическую» («Ифигению-жрицу»). «Умоляющие» и «Троянки» остались неизданными и долго считались потерянными."],["p","Сабашниковское издание выходило под редакцией Ф. Ф. Зелинского. Свои редакторские права он понял очень широко и не только снабдил его примечаниями и статьями (к тем драмам, к которым Анненский не успел их написать), но и внес большую правку в стихотворный текст Анненского — чтобы приблизить перевод к подлиннику и отчасти чтобы (по своему разумению) улучшить стиль. Исправлены и переписаны были подчас по четверти и более строк в каждой трагедии. Те, кому дороже был Еврипид, радовались; те, кому дороже был Анненский (прежде всего наследники поэта), негодовали; вспыхнул газетный скандал (материалы его напечатаны в предисловии ко второму сабашниковскому тому). Последствий это не имело, так как издание оборвалось на следующем томе."],["p","Следующее издание — первое полное издание Еврипида на русском языке — вышло лишь в 1969 г. в издательстве «Художественная литература» в двух томах под ред. В. Н. Ярхо. Здесь текст Анненского был по большей части восстановлен: все трагедии, напечатанные самим поэтом, воспроизводились по этим прижизненным изданиям, и лишь «Вакханки» (самый ранний и неудачный из переводов Анненского) и некоторые места в других трагедиях печатались по редактуре Зелинского. Однако в это издание была внесена редактура другого рода: были выброшены все фантастические ремарки Анненского (пощаженные Зелинским), а членение текста на «действия», «музыкальные антракты» и «исход» было заменено членением на «эписодии», «стасимы» и «эксод». Трагедии «Просительницы» («Умоляющие») и «Троянки» были напечатаны в переводе С. В. Шервинского, сделанном специально для этого издания. В 1980 г. это издание было повторено (с новым комментарием) в издательстве «Искусство»; «Просительниц» и «Троянок» для него перевел С. К. Апт (хотя в это время уже стало известно, что, по крайней мере, первая в переводе Анненского сохранилась в архивной рукописи)."],["p","Предлагаемое читателю новое издание впервые дает полного Еврипида в подлинном переводе И. Ф. Анненского. Все трагедии, печатавшиеся при жизни поэта, воспроизводятся по этим прижизненным изданиям, включая и «Вакханок». Правка Зелинского снята не только там, где его текст можно было сверить с прижизненными изданиями, но и там, где его можно было сверить с рукописями, хранящимися в фонде Анненского в РГАЛИ — в «Андромахе», «Ифигении в Тавриде» и первых 483 стихах «Гекубы». Таким образом, редактура Зелинского поневоле сохраняется только в «Гераклидах», «Елене» и частично в «Гекубе», рукописи которых остаются недоступны. Ремарки Анненского всюду восстановлены. Мы позволили себе лишь унифицировать транскрипцию некоторых собственных имен («Пенфей» вместо «Пентей», «Гекуба» вместо «Гекаба», «Итака» вместо «Ифака», «Тесей» вместо «Фесей»). «Умоляющие» печатаются по наборной копии, сохранившейся в архиве издательства Сабашниковых в рукописном отделе РГБ. «Троянки» печатаются по автографу (отчасти беловому, отчасти черновому), сохранившемуся в архивном фонде И. Анненского в РГАЛИ. Архивной сверкой текста занимался М. Л. Гаспаров. Составители приносят глубокую благодарность В. Гитину, который поделился с ними материалом подготовленной им книги «Неизданный »Театр Еврипида« Анненского» («Умоляющие» и «Троянки» с сопровождающими их статьями, статьи Анненского «Еврипид и его время» и «Афины V века» и др.) — это позволило уточнить многие чтения в неразборчивом черновике «Троянок»."],["p","«Алькеста» была поставлена на Великих Дионисиях в 438 г. до н. э, в составе тетралогии, в которую входили несохранившиеся трагедии «Критянки», «Алкмеон в Псофиде» и «Телеф». Поскольку «Алькеста» занимала здесь четвертое место, обычно отводимое для драмы сатиров, некоторые исследователи стремятся найти в этой драме юмористические или даже бурлескные ситуации, но такие попытки едва ли основательны: бытовой элемент, несомненно присутствующий в образе Ферета, обрисованного не без доли иронии, в принципе не отличает его существенно хотя бы от кормилицы в «Ипполите», а в этой трагедии никто не станет искать черты драмы сатиров. Близость «Алькесты» к названному жанру пытались усмотреть также в образе Геракла — одного из любимых персонажей драмы сатиров, комедии и народного фарса; между тем в «Алькесте» Геракл играет самую положительную роль, и его борьба с демоном смерти за ушедшую из жизни Алькесту как раз приводит трагедию к счастливой развязке, позволившей Еврипиду заключить ею тетралогию. Именно благополучный конец, отнюдь не частый в трагедиях Еврипида 430-420-х годов, скорее всего объясняет постановку «Алькесты» вместо сатировской драмы, к которой наш поэт вообще не испытывал особого влечения (см. т. II, с. 600)."],["p","Тетралогия, которую заключала «Алькеста», заняла второе место; первая награда была присуждена Софоклу."],["p","Хотя гомеровский эпос знает имена Адмета, Алькесты и их сына Евмела, участника Троянской войны («Илиада», II, 713 — 715, 763; XXIII, 288 — 289 и сл.), в поэмах нет никаких намеков на миф о добровольной смерти и воскресении Алькесты; он был обработан впервые, по-видимому, только в каталогообразной поэме «Зои», приписывавшейся Гесиоду. От нее дошли лишь незначительные отрывки, и содержание мифа известно по позднеантичным пересказам. Из предшественников Еврипида сюжет «Алькесты» получил обработку в несохранившейся одноименной драме аттического трагика Фриниха (первая четверть V в.), из которой Еврипид заимствовал образ бога смерти Танатоса (у Анненского он назван демоном смерти) и его борьбу с Гераклом за умершую Алькесту."],["p","Имя героини трагедии Alcesus, на русском языке правильнее всего транскрибируется «Алкестида». Анненский предпочел вариант «Алькеста», легче ложившийся в стих; Ф. Ф. Зелинский по своему усмотрению переделал его в «Алкесту». В «Театре Еврипида» 1906 г. трагедия напечатана с посвящением Е. М. Мухиной, жене педагога — сослуживца Анненского и его постоянной корреспондентке, и с эпиграфом «The strangest, saddest, sweetest song of his / Alcestis… — R. Browning» («…самая странная, скорбная, сладкая песнь о его Алкестиде…») — из поэмы Р. Браунинга на сюжет легенды о том, как афинские пленники на чужбине получили свободу за то, что спели победителям песни из последних трагедий Еврипида."],["ed","В.Н. Ярхо"],["note","k1"],["note","k2"],["note","k3"],["note","k4"],["note","k5"],["note","k6"],["note","k7"],["note","k8"],["note","k9"],["note","k10"],["note","k11"],["note","k12"],["note","k13"],["note","k14"],["note","k15"],["note","k16"],["note","k17"],["note","k18"],["note","k19"],["note","k20"],["note","k21"],["note","k22"],["note","k23"],["note","k24"],["note","k25"],["note","k26"],["note","k27"],["note","k28"],["note","k29"],["note","k30"],["note","k31"],["note","k32"],["note","k33"],["note","k34"],["note","k35"],["note","k36"],["note","k37"],["note","k38"]],"n":{"k1":["Ст. 3. …Асклепия сразил он…","Когда сын Аполлона Асклепий, слывший искуснейшим врачом, попытался оживить умершего, Зевс поразил его молнией. Разгневанный Аполлон, бессильный отомстить Зевсу, убил тех, кто изготовил смертоносный огонь, — киклопов, и за это был отдан в рабство Адмету (ср. ст. 122 — 129)."],"k2":["Ст. 11. Девы судьбы","Мойры."],"k3":["Ст. 23. …вежд да не коснется скверна.","Богам не подобает созерцать смерть людей (ср. «Ипполит», ст. 1437 сл.)."],"k4":["Ст. 38. …истина и слава.","В подлиннике — «справедливость и обоснованность»: Зелинский исправлял: «честь и правда»."],"k5":["Ст. 65. …от Еврисфея муж… зайдет…","Геракл, отправляющийся за конями фракийского царя Диомеда (ст. 481 — 498); к этому эпизоду Еврипид приурочивает посещение Гераклом дома Адмета. Слова Аполлона (ст. 65 — 71) характерны для драматической техники Еврипида, любившего сообщать о развязке трагедии задолго до ее наступления."],"k6":["Ст. 92. Пеан","«целитель», «избавитель»; культовое прозвище Аполлона."],"k7":["Ст. 99. Обряд воды ключевой.","Чтобы очиститься от скверны, навлекаемой соприкосновением с покойником или даже одним его видом, у дома, который посетила смерть, ставили чаши с ключевой водой для омовения рук."],"k8":["Ст. 101","…сбритых волос… — Обычно пряди волос, обрезанные в дар умершему, оставляли на его могиле, а не у дверей дома."],"k9":["Ст. 112-135","Встречающиеся у Анненского переводы хоровых партий рифмованным стихом, не свойственным древнегреческой поэзии, представляют один из возможных способов передачи на русском языке музыкально-ритмической структуры, присущей оригиналу."],"k10":["Ст. 114-116. …Ликийской земли…","В Ликии (в Малой Азии) находился известный храм Аполлона; святилище Зевса-Аммона — в Ливии (Сев. Африка)."],"k11":["Ст. 163. Взмолилася владычице…","скорее всего, Гестии, хранительнице домашнего очага."],"k12":["Ст. 177-182","Прощание Алькесты с брачным ложем сравнивают обычно со словами Деяниры из «Трахинянок» Софокла (ст. 920-922), видя в последних результат влияния Еврипида на своего старшего собрата по искусству."],"k13":["Ст. 206. Ей хочется на солнце.","После этого стиха в рукописях следуют еще два стиха, обычно изымаемые издателями, так как они повторяют ст. 411 сл. из «Гекубы». Вот их перевод:<br>Ведь навеки<br>Она с его сиянием лучистым<br>Прощается сегодня."],"k14":["Ст. 226. Увы!","После этого восклицания в рукописях утерян один стих, дававший ритмическое соответствие ст. 213 в строфе."],"k15":["Ст. 393-415. Монодия Евмела","первый случай в сохранившихся древнегреческих трагедиях, когда дети имеют самостоятельную партию. Другой пример — в «Андромахе», ст. 504 — 536."],"k16":["Ст. 424. Пеан","здесь: траурная песнь, обращенная к подземным богам."],"k17":["Ст. 431. Двенадцать лун…","траур необыкновенной продолжительности; в Афинах полагалось носить траур по родителям в течение одного месяца."],"k18":["Ст. 445 — 450","Подвиг Алькесты будет воспет, по мнению хора, на мусических состязаниях в честь Аполлона Карнейского в Спарте («семиструнной лирой») и в трагедиях (безлирным гимном\", так как трагедийные хоры исполнялись в сопровождении флейты). В афинском театре сказание об Алькесте послужило сюжетом уже упомянутой драмы Фриниха."],"k19":["Ст. 459. Кокит","река в подземном царстве."],"k20":["Ст. 485. Бистоны","фракийское племя."],"k21":["Ст. 502. Ликаон, Кикн.","Сражение Геракла с Ликаоном в других источниках не упоминается, единоборство же с Кикном составляет сюжет приписываемой Гесиоду поэмы «Щит Геракла». Ср. также «Геракл» Еврипида, ст. 389 сл."],"k22":["Ст. 509. Персеид.","По мифологической генеалогии, Геракл приходился правнуком Персею. См. примеч. к «Гераклидам», ст. 36. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Гераклиды», Ст. 36. В них кровь одна с Геракловым потомством….</b> Еврипид следует здесь тому варианту мифологической генеалогии, по которому Алкмена, мать Геракла, и Эфра, мать Тесея, являлись обе внучками Пелопа. В свою очередь, Алкмена и Еврисфей являются двоюродными братом и сестрой, так как их отцы — сыновья Персея, а матери — дочери Пелопа (см. также ст. 207-212, 987 и сл.).</span><!--/xn-->"],"k23":["Ст. 560. …хозяин мой","Геракл. — Адмет связан с Гераклом древним обычаем проксении, т. е. взаимного гостеприимства, целиком сохранявшим свое значение во времена Еврипида."],"k24":["Ст. 570 сл. Бог пифийский","Аполлон. Хор вспоминает о пребывании Аполлона в Фессалии."],"k25":["Ст. 580. Офрис","гора в Фессалии."],"k26":["Ст. 590. Бебида","озеро в Фессалии."],"k27":["Ст. 594. От Молосского предела.","Племя молоссов населяло горные районы северо-западной Греции."],"k28":["Ст. 638 сл. …едва ли ты даже был моим отцом…","Этот стих и следующие, вынесенные в примечание, многие исследователи считают неподлинными: гордый своим происхождением, Адмет не мог бы во всеуслышание объявлять себя сыном рабыни."],"k29":["Ст. 747","Относительно редкий случай в древнегреческой трагедии, когда хор покидает орхестру, чтобы снова вернуться перед заключительной частью драмы (ст. 861 сл.). Аналогичный прием в «Аяксе» Софокла (ст. 813 сл. и 866)."],"k30":["Ст. 818 сл","Стихи, вынесенные в примечание, исключаются большинством издателей как неподлинные и нарушающие принцип стихомифии."],"k31":["Ст. 903-910","В этой строфе видят намек либо на философа Анаксагора, потерявшего единственного сына, либо на несчастье, постигшее самого Еврипида."],"k32":["Ст. 968. …вещая речь Орфея…","Традиция приписывала Орфею целую совокупность философских, этических и медицинских наставлений (так называемое учение орфиков), в том числе рекомендации для исцеления от физической и душевной боли."],"k33":["Ст. 971. Асклепиады","врачи, служители Асклепия."],"k34":["Ст. 980. Халибы","легендарное племя, по представлению древних обитавшее в Южном Причерноморье; халибы считались особо искусными в обработке железа."],"k35":["Ст. 1119","Стих разделен на три реплики, как и ст. 391. Там Адмет терял Алькесту, здесь вновь ее обретает."],"k36":["Ст. 1128. Гермес","здесь он назван как посредник между земным и подзем- ным миром."],"k37":["Ст. 1150. Царь, рожденный Сфенелом,","Еврисфей."],"k38":["Ст. 1154. …всех четырех концов Фессалии…","В историческую эпоху Фессалия, где находился город Феры — резиденция легендарного Адмета, делилась на четыре области — тетрархии. Однако Феры сами входили в состав одной из таких тетрархий — Пеласгиотиды, а не являлись самостоятельной тетрархией, и владения их отнюдь не простирались так широко, как об этом поет хор в ст. 588-596."]},"mainEnd":1852,"c":[{"id":"alkesta","name":"Алькеста","role":"Жена фессалийского царя Адмета, дочь Пелия","intro":"Царица, согласившаяся умереть вместо мужа, когда этого не захотел никто другой.","arc":"Аполлон выпросил у Мойр для Адмета право откупиться от смерти чужой жизнью; старые родители отказались, согласилась только жена. Алькеста у Еврипида не экзальтированная героиня, а трезвая хозяйка дома: прощаясь, она думает о детях и берёт с мужа слово не приводить им мачеху. Её жертва становится мерилом для всех остальных — для Адмета, Ферета, Геракла. Возвращённая из Аида, она молчит: три дня она ещё принадлежит подземным богам.","st":[{"i":336,"p":18,"l":"Действие первое · явление пятое","t":"Прощание с домом","d":"Служанка рассказывает хору, как царица в последний день омылась, убрала себя, помолилась Гестии за детей и, наконец, разрыдалась над брачным ложем.","c":"Смерть уже решена; о самой Алькесте мы сначала узнаём со слов других.","k":false},{"i":708,"p":38,"l":"Действие первое · явление шестое","t":"Смерть на руках мужа","d":"Выходит на солнце, видит ладью Харона. Просит Адмета не вводить в дом мачеху и умирает; сын Евмел оплакивает мать.","c":"Её последняя воля — обет, который Адмет вскоре нарушит из гостеприимства.","k":true},{"i":1832,"p":99,"l":"Исход · явление семнадцатое","t":"Возвращение под покрывалом","d":"Геракл приводит закутанную женщину и уговаривает Адмета принять её. Сняв покрывало, тот узнаёт жену; она пока не может говорить.","c":"Жертва возвращена тому, кто сумел сохранить и верность умершей, и долг хозяина.","k":false}],"gen":"Алкеста"},{"id":"admet","name":"Адмет","role":"Царь Фер в Фессалии","intro":"Счастливый царь, который принял чужую смерть за себя и только потом понял её цену.","arc":"Адмет — самая неоднозначная фигура пьесы: он искренне любит жену и всё же согласился, чтобы она умерла за него. Его благородство проявляется в гостеприимстве — он скрывает траур от Геракла, — его эгоизм обнажается в ссоре с отцом, которого он упрекает в трусости. Вернувшись с похорон, он впервые сознаёт, что купил себе жизнь бесчестьем. Этим прозрением и верностью долгу хозяина он заслуживает возвращения Алькесты.","st":[{"i":708,"p":38,"l":"Действие первое · явление шестое","t":"Смерть жены","d":"Обещает Алькесте вечный траур, клянётся не жениться и не впускать в дом веселья.","c":"Он принимает её жертву, хотя и с мукой.","k":false},{"i":918,"p":50,"l":"Действие второе · явление восьмое","t":"Гостеприимство в трауре","d":"Встретив Геракла, скрывает, кто умер: «чужая женщина, выросшая в доме». Велит принять гостя в дальних покоях.","c":"Святыня гостеприимства для него выше собственного горя — и это станет спасением.","k":true},{"i":1189,"p":64,"l":"Действие третье · явление одиннадцатое","t":"Ссора с Феретом","d":"Отец приходит с дарами на похороны; Адмет отвергает его и упрекает в том, что тот, старик, пожалел для сына жизни. Ферет отвечает: «Ты сам любишь жизнь — и отдал жену».","c":"Обвиняя отца, Адмет невольно обвиняет себя.","k":false},{"i":1497,"p":81,"l":"Действие третье · Коммос","t":"Возвращение в пустой дом","d":"После похорон, в коммосе с хором, понимает, что жить ему теперь невыносимо, а люди будут звать его трусом.","c":"Прозрение: жизнь, купленная чужой смертью, не стоит того.","k":true},{"i":1851,"p":100,"l":"Исход · явление восемнадцатое,","t":"Новая жизнь","d":"Получив жену из рук Геракла, велит городу праздновать: «Мы теперь для лучшей жизни обновились».","c":"","k":false}],"gen":"Адмет"},{"id":"gerakl","name":"Геракл","role":"Сын Зевса, друг Адмета","intro":"Герой на пути к своему восьмому подвигу, который случайно попадает в дом в день похорон.","arc":"Геракл в «Алькесте» почти сатировская фигура: он пирует, поёт и поучает слугу пить и радоваться жизни. Узнав правду, он стыдится и становится тем, кто способен победить саму Смерть. Через него пьеса получает свой счастливый, почти сказочный конец.","st":[{"i":1339,"p":72,"l":"Действие третье · явление четырнадцатое","t":"Пир в доме печали","d":"Захмелевший Геракл поучает угрюмого слугу радоваться жизни — и узнаёт, что хоронят саму царицу.","c":"Пристыженный, он понимает благородство Адмета.","k":false},{"i":1371,"p":74,"l":"Действие третье · явление пятнадцатое","t":"Решение бороться со Смертью","d":"Решает подстеречь Танатоса у могилы и отбить у него Алькесту.","c":"Ответ на гостеприимство — подвиг.","k":true},{"i":1832,"p":99,"l":"Исход · явление семнадцатое","t":"Испытание Адмета","d":"Приводит закутанную женщину, будто бы выигранную на играх, и настаивает, чтобы Адмет принял её в дом. Лишь потом открывает её лицо.","c":"Проверяет верность друга — и возвращает ему жену.","k":false}],"gen":"Геракл"},{"id":"feret","name":"Ферет","role":"Отец Адмета","intro":"Старик, отказавшийся умереть за сына.","arc":"Ферет — единственный, кто говорит в пьесе неприятную правду: каждый любит свет солнца, и Адмет, укоряющий других, сам принял чужую смерть.","st":[{"i":1189,"p":64,"l":"Действие третье · явление одиннадцатое","t":"Спор над телом невестки","d":"Приносит погребальный убор, слышит проклятия сына и отвечает ему жёстко и откровенно.","c":"Его отповедь лишает Адмета права на чистую совесть.","k":true}],"gen":"Ферет"}]};
